window.ScripturaLexicons.BDAG_PART_0383 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-01\" data-source=\"BDAG\" data-search=\"φυσικός, ή, όν adjetivo natural BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φυσικός, ή, όν</td><td>adjetivo</td><td>natural</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-02\" data-source=\"BDAG\" data-search=\"φυσικῶς advérbio naturalmente; por instinto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φυσικῶς</td><td>advérbio</td><td>naturalmente; por instinto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-03\" data-source=\"BDAG\" data-search=\"φυσιόω verbo ensoberbecer; tornar orgulhoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φυσιόω</td><td>verbo</td><td>ensoberbecer; tornar orgulhoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-04\" data-source=\"BDAG\" data-search=\"φύσις, εως, ἡ substantivo feminino natureza; condição natural; criatura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φύσις, εως, ἡ</td><td>substantivo feminino</td><td>natureza; condição natural; criatura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-05\" data-source=\"BDAG\" data-search=\"φυσίωσις, εως, ἡ substantivo feminino presunção; orgulho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φυσίωσις, εως, ἡ</td><td>substantivo feminino</td><td>presunção; orgulho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-06\" data-source=\"BDAG\" data-search=\"φυτεία, ας, ἡ substantivo feminino planta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φυτεία, ας, ἡ</td><td>substantivo feminino</td><td>planta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-07\" data-source=\"BDAG\" data-search=\"φυτεύω verbo plantar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φυτεύω</td><td>verbo</td><td>plantar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-08\" data-source=\"BDAG\" data-search=\"φυτόν, οῦ, τό substantivo neutro planta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φυτόν, οῦ, τό</td><td>substantivo neutro</td><td>planta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-09\" data-source=\"BDAG\" data-search=\"φύω verbo crescer; brotar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φύω</td><td>verbo</td><td>crescer; brotar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-10\" data-source=\"BDAG\" data-search=\"φωλεός, οῦ, ὁ substantivo masculino toca; covil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φωλεός, οῦ, ὁ</td><td>substantivo masculino</td><td>toca; covil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-11\" data-source=\"BDAG\" data-search=\"φωνέω verbo emitir voz; chamar; convocar; convidar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φωνέω</td><td>verbo</td><td>emitir voz; chamar; convocar; convidar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-12\" data-source=\"BDAG\" data-search=\"φωνή, ῆς, ἡ substantivo feminino som; voz; declaração; língua BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φωνή, ῆς, ἡ</td><td>substantivo feminino</td><td>som; voz; declaração; língua</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-13\" data-source=\"BDAG\" data-search=\"φῶς, φωτός, τό substantivo neutro luz; fonte de luz; aquilo que é iluminado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φῶς, φωτός, τό</td><td>substantivo neutro</td><td>luz; fonte de luz; aquilo que é iluminado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-14\" data-source=\"BDAG\" data-search=\"φωστήρ, ῆρος, ὁ substantivo masculino astro; estrela; esplendor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φωστήρ, ῆρος, ὁ</td><td>substantivo masculino</td><td>astro; estrela; esplendor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-15\" data-source=\"BDAG\" data-search=\"φωσφόρος, ον adjetivo; substantivado portador de luz; estrela da manhã BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φωσφόρος, ον</td><td>adjetivo; substantivado</td><td>portador de luz; estrela da manhã</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-16\" data-source=\"BDAG\" data-search=\"φωταγωγός, ον adjetivo que traz luz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φωταγωγός, ον</td><td>adjetivo</td><td>que traz luz</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-17\" data-source=\"BDAG\" data-search=\"φωτεινός, ή, όν adjetivo brilhante; iluminado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φωτεινός, ή, όν</td><td>adjetivo</td><td>brilhante; iluminado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-18\" data-source=\"BDAG\" data-search=\"φωτίζω verbo brilhar; iluminar; revelar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φωτίζω</td><td>verbo</td><td>brilhar; iluminar; revelar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-19\" data-source=\"BDAG\" data-search=\"φωτισμός, οῦ, ὁ, substantivo masculino iluminação; revelação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φωτισμός, οῦ, ὁ,</td><td>substantivo masculino</td><td>iluminação; revelação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0383-20\" data-source=\"BDAG\" data-search=\"χαίρω verbo alegrar-se; saudar; despedir-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χαίρω</td><td>verbo</td><td>alegrar-se; saudar; despedir-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0383-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυσικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φυσικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (de <span class=\"greek\">φύω</span> por intermédio de <span class=\"greek\">φύσις</span>; X.+; PLips 28, 18; EpArist 222 e outros lugares; TestDan 2:4; 3:4; Philo; Jos., Ant. 12, 99; Ar. 13:7; Just., D. 39, 1; Ath.; <span class=\"greek\">φυσικώτερον</span> Tat. 21, 2) relativo à conformidade com a ordem fundamental das coisas na natureza</p><p class=\"entry-text\">ⓐ do comportamento humano, natural (Dionys. Hal., Plut. e outros <span class=\"greek\">φυσικὴ</span> <span class=\"greek\">χρῆσις</span>) Ro 1:26f.</p><p class=\"entry-text\">ⓑ de animais, cujo destino natural é ser vítimas de predadores, em conformidade com a natureza <span class=\"greek\">γεγεννημένα</span> <span class=\"greek\">φυσικὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἅλωσιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φθοράν</span> (meras) criaturas de instinto, nascidas para ser capturadas e mortas 2 Pt 2:12.—DELG s.v. <span class=\"greek\">φύομαι</span> C 6. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυσικῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φυσικῶς</span> adv. de <span class=\"greek\">φυσικός</span>; comp. <span class=\"greek\">φυσικώτερον</span> (Tat. 26, 3) (Aristot., Diod S, Plut., Philo e outros) naturalmente, por instinto Jd 10 (cf. Diog. L, 10, 137 <span class=\"greek\">φυσικῶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">χωρὶς</span> <span class=\"greek\">λόγου</span> e outros lugares; X., Cyr. 2, 3, 9 <span class=\"greek\">μάχην</span> <span class=\"greek\">ὁρῶ</span> <span class=\"greek\">πάντας</span> <span class=\"greek\">ἀνθρώπους</span> <span class=\"greek\">φύσει</span> <span class=\"greek\">ἐπισταμένους</span>, <span class=\"greek\">ὥσπέρ</span> <span class=\"greek\">γε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τἄλλα</span> <span class=\"greek\">ζῷα</span> <span class=\"greek\">ἐπίσταταί</span> <span class=\"greek\">τινα</span> <span class=\"greek\">μάχην</span> <span class=\"greek\">ἕκαστα</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">ἄλλου</span> <span class=\"greek\">μαθόντα</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">φύσεως</span> ‘percebo que todos os seres humanos têm conhecimento natural do combate, assim como as outras criaturas conhecem, cada qual, algum modo de lutar, sem terem aprendido coisa alguma de outro, mas simplesmente por instinto’).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυσιόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φυσιόω</span> (substituto posterior de <span class=\"greek\">φυσάω</span>; restringe-se em grande parte à literatura cristã [mas também em Philod., Mus. p. 26 JKemke 1884]) pass.: partic. perf. <span class=\"greek\">πεφυσιωμένος</span>; 1.º aor. <span class=\"greek\">ἐφυσιώθην</span> lit. ‘encher de ar, inflar’ de <span class=\"greek\">φῦσα</span> (originalmente ‘fole’, depois, variadamente, ‘vento, sopro’ etc.) fig. fazer que alguém tenha uma concepção exagerada de si mesmo, ensoberbecer, tornar orgulhoso <span class=\"greek\">τινά</span> alguém ITr 4:1. <span class=\"greek\">τόπος</span> <span class=\"greek\">μηδένα</span> <span class=\"greek\">φυσιούτω</span> que ninguém se ensoberbeça por causa de posição (elevada) ISm 6:1. Do conhecimento <span class=\"greek\">φυσιοῖ</span> ele (apenas) ensoberbece <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:1</a>=Dg 12:5.—Pass. em sentido ativo, ensoberbecer-se ou tornar-se presunçoso, ostentar ares de importância (TestLevi 14:7, 8 v.l.; escólio a Apollon. Rhod. 3, 368b da ira, que incha o coração; Hesych.; cf. Babrius 114 v.l. L-P. [=349 P.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:18f</a>; 5:2; 13:4; IMg 12; ITr 7:1; IPol 4:3. <span class=\"greek\">εἰκῇ</span> <span class=\"greek\">φυσιούμενος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νοὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">αὐτοῦ</span> ensoberbecido sem fundamento por sua mente carnal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:18.</a> <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εἷς</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">φυσιοῦσθε</span> (talvez subjuntivo; v. <span class=\"greek\">ἵνα</span> 1c) <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἑτέρου</span> para que nenhum de vós se ensoberbeça a favor de um (apóstolo e, assim,) contra o outro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:6.</a>—B. 684. DELG s.v. <span class=\"greek\">φῦσα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φύσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φύσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">φύω</span>; Hom.+)</p><p class=\"entry-text\">① condição ou circunstância determinada pelo nascimento, dotação/condição natural, natureza, especialmente enquanto herdada dos antepassados, em contraste com posição ou características adquiridas após o nascimento (Isocr. 4, 105 <span class=\"greek\">φύσει</span> <span class=\"greek\">πολίτης</span>; Isaeus 6, 28 <span class=\"greek\">φύσει</span> <span class=\"greek\">υἱός</span>; Pla., Menex. 245d <span class=\"greek\">φύσει</span> <span class=\"greek\">βάρβαροι</span>, <span class=\"greek\">νόμῳ</span> <span class=\"greek\">Ἕλληνες</span>; Just., A I, 1, 1 <span class=\"greek\">Καίσαρος</span> <span class=\"greek\">φύσει</span> <span class=\"greek\">υἱῷ</span>; SIG 720, 3; OGI 472, 4; 558, 6 e outros lugares; PFay 19, 11.—Theoph. Ant. 1, 13 [p. 86, 16]) <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">φύσει</span> <span class=\"greek\">Ἰουδαῖοι</span> Gal 2:15 (cf. Ptolemaeus, <span class=\"greek\">Περὶ</span> <span class=\"greek\">Ἡρῴδου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βασιλέως</span>: n.º 199 Jac. [I d.C.] <span class=\"greek\">Ἰουδαῖοι</span> … <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀρχῆς</span> <span class=\"greek\">φυσικοί</span>; Jos., Ant. 7, 130; <span class=\"greek\">φύσει</span> <span class=\"greek\">Λιμναίου</span> IK XXXVII, 15, 3 da filha de nascimento de L. em contraste com sua relação adotiva com alguém chamado Arsas). <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">φύσεως</span> <span class=\"greek\">ἀκροβυστία</span> a incircuncisão que o é por natureza (referência aos não israelitas, que carecem da formação moral dos circuncidados e, contudo, ‘observam as justas exigências da lei’ [Ro 2:26]. Os israelitas que violam suas responsabilidades para com Deus, apesar da posição privilegiada indicada pelo recebimento da circuncisão e da revelação especial, correm o risco de se colocar na condição dos incircuncisos) Ro 2:27. <span class=\"greek\">ἤμεθα</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">φύσει</span> <span class=\"greek\">ὀργῆς</span> éramos, em nossa condição natural (como descendentes de Adão), sujeitos à ira (de Deus) Eph 2:3 (a posição de <span class=\"greek\">φύσει</span> entre as duas palavras como em Plut., Mor. 701a; DTurner, Grace Theological Journal 1, ’80, 195–219). Os cristãos de Trales têm uma disposição irrepreensível <span class=\"greek\">οὐ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">χρῆσιν</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">φύσιν</span> não por hábito, mas por natureza ITr 1:1 (aqui o contraste é entre a virtude meramente formal e o comportamento espontâneo ou instintivo; Píndaro igualmente exaltava as virtudes dos atletas que, em contraste com os de mera instrução adquirida, refletiam sua formação ancestral para a excelência: O. 7, 90–92; P. 10, 11–14; N. 3, 40–42; 6, 8–16). <span class=\"greek\">οἱ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">φύσιν</span> <span class=\"greek\">κλάδοι</span> os ramos naturais Ro 11:21, 24c. <span class=\"greek\">ἡ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">φύσιν</span> <span class=\"greek\">ἀγριέλαιος</span> árvore que por natureza é uma oliveira brava v. 24a; oposto <span class=\"greek\">παρὰ</span> <span class=\"greek\">φύσιν</span> contra a natureza v. 24b; v. literatura s.v. <span class=\"greek\">ἀγριέλαιος</span> e <span class=\"greek\">ἐλαία</span> 1. Sobre <span class=\"greek\">κατὰ</span> e <span class=\"greek\">παρὰ</span> <span class=\"greek\">φύσιν</span> v. MPohlenz, Die Stoa I ’48, 488c.</p><p class=\"entry-text\">② o caráter natural de uma entidade, característica/disposição natural (<span class=\"greek\">χρυσὸς</span> … <span class=\"greek\">τὴν</span> <span class=\"greek\">ἰδίαν</span> <span class=\"greek\">φ</span>. <span class=\"greek\">διαφυλάττει</span> Iren. 1, 6, 2 [Harv. I 55, 2]; Hippol., Ref. 5, 8, 12) <span class=\"greek\">ἡ</span> <span class=\"greek\">φύσις</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀνθρωπίνη</span> natureza humana (Pla., Tht. 149b, Tim. 90c; Aristot. 1286b, 27; Epict. 2, 20, 18; Philo, Ebr. 166 e outros lugares; Aelian, VH 8, 11 <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">φύσις</span> <span class=\"greek\">θνητή</span>; TestJob 3:3 <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀνθρωπίνη</span> <span class=\"greek\">φ</span>.; Orig., C. Cels. 1, 52, 13; Just., A II, 6, 3 <span class=\"greek\">τῇ</span> <span class=\"greek\">φύσει</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span>) Js 3:7b (a menos que o sentido seja humanidade, v. 4 abaixo). Eufemisticamente: <span class=\"greek\">παρθένος</span> <span class=\"greek\">ἐγέννησεν</span>, <span class=\"greek\">ἃ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">χωρεῖ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">φύσις</span> <span class=\"greek\">αὐτῆς</span> permanecendo virgem, uma virgem teve um filho ou uma virgem deu à luz, algo que não condiz com sua condição natural (de virgem) GJs 19:3. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀδύνατον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμετέρας</span> <span class=\"greek\">φύσεως</span> a fraqueza de nossa natureza Dg 9:6. <span class=\"greek\">θείας</span> <span class=\"greek\">κοινωνοὶ</span> <span class=\"greek\">φύσεως</span> participantes da natureza divina 2 Pt 1:4 (cf. <span class=\"greek\">ὅσοι</span> <span class=\"greek\">φύσεως</span> <span class=\"greek\">κοινωνοῦντες</span> <span class=\"greek\">ἀνθρω</span>[<span class=\"greek\">πίν</span>]<span class=\"greek\">ης</span> IReisenKN, p. 371, 46f; Jos., C. Ap. 1, 232 <span class=\"greek\">θείας</span> <span class=\"greek\">μετεσχηκέναι</span> <span class=\"greek\">φύσεως</span>; Himerius, Or. 48 [=Or. 14], 26 de Dioniso: <span class=\"greek\">πρὶν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">φύσιν</span> <span class=\"greek\">ἐλθεῖν</span>=antes de alcançar a natureza dos deuses; Ar. 13, 5 <span class=\"greek\">μία</span> <span class=\"greek\">φ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span>. Diferentemente AWolters, Calvin Theological Journal 25, ’90, 28–44 ‘parceiros da Divindade’).—Também especificamente de características sexuais (Diod S 16, 26, 6 originalmente <span class=\"greek\">παρθένοι</span> profetizavam em Delfos <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">φύσεως</span> <span class=\"greek\">ἀδιάφθορον</span>=porque sua sexualidade era incorrupta. <span class=\"greek\">φύσις</span> do sexo e de sua mudança Dicaearchus, Fgm. 37 W.; <span class=\"greek\">ἑρμαφροδίτου</span> <span class=\"greek\">φ</span>. Iren. 1, 11, 5 [Harv. I 108, 8]. Evidentemente <span class=\"greek\">φ</span>. tem também o sentido concreto de ‘órgão sexual’: Nicander, Fgm. 107; Diod S 32, 10, 7 <span class=\"greek\">φ</span>. <span class=\"greek\">ἄρρενος</span> em correspondência com <span class=\"greek\">φ</span>. <span class=\"greek\">θηλείας</span> imediatamente a seguir; Anton. Lib. 41, 5; Phlegon: 257 Fgm. 36, 2, 1 Jac.). No contexto do parto virginal de Maria <span class=\"greek\">ἐραυνήσω</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φύσιν</span> <span class=\"greek\">αὐτῆς</span>=examinarei se ela permanece virgem GJs 19:3b; 20:1 (onde Tdf. com os códices lê <span class=\"greek\">ἔβαλε</span> <span class=\"greek\">Σαλώμη</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">δάκτυλον</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φύσιν</span> <span class=\"greek\">αὐτῆς</span> [cf. J 20:25]). A hiena <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἐνιαυτὸν</span> <span class=\"greek\">ἀλλάσσει</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φύσιν</span> muda sua natureza anualmente, de macho para fêmea e vice-versa B 10:7 (v. <span class=\"greek\">ὕαινα</span>). Os politeístas adoram <span class=\"greek\">τοῖς</span> <span class=\"greek\">φύσει</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">οὖσιν</span> <span class=\"greek\">θεοῖς</span> seres que por natureza absolutamente não são deuses Gal 4:8 (v. CLanger, Euhemeros u. die Theorie der <span class=\"greek\">φύσει</span> u. <span class=\"greek\">θέσει</span> <span class=\"greek\">θεοί</span>: <span class=\"greek\">Αγγελος</span> II 1926, 53–59; Mel., P. 8, 58 <span class=\"greek\">φύσει</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄνθρωπος</span>; Synes., Prov. 1, 9 p. 97c <span class=\"greek\">τοῖς</span> <span class=\"greek\">φύσει</span> <span class=\"greek\">θεοῖς</span>; Diod S 3, 9, 1 distingue duas espécies de deuses: alguns <span class=\"greek\">αἰώνιον</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἄφθαρτον</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φύσιν</span>, outros <span class=\"greek\">θνητῆς</span> <span class=\"greek\">φύσεως</span> <span class=\"greek\">κεκοινωνηκέναι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δι</span>’ <span class=\"greek\">ἀρετὴν</span> … <span class=\"greek\">τετευχέναι</span> <span class=\"greek\">τιμῶν</span> <span class=\"greek\">ἀθανάτων</span>=alguns ‘têm natureza eterna e incorruptível’, outros ‘participam da natureza mortal e então, por sua excelência pessoal, … alcançam honras imortais’).—<span class=\"greek\">ὅταν</span> <span class=\"greek\">ἔθνη</span> <span class=\"greek\">φύσει</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> <span class=\"greek\">ποιῶσιν</span> quando os gentios espontaneamente (isto é, sem instrução legal externa; cf. o ideal profético Jer 31:32–34) cumprem as exigências da lei (mosaica) Ro 2:14 (v. WMundle, Theol. Blätter 13, ’34, 249–56 [o gentio como cristão sob a direção do <span class=\"greek\">πνεῦμα</span>]; diferentemente v. 3 abaixo).</p><p class=\"entry-text\">③ a ordem regular ou estabelecida das coisas, natureza (Ar. 4, 2 <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἀπαραίτητον</span> <span class=\"greek\">φύσεως</span> <span class=\"greek\">ἀνάγκην</span>=em conformidade com a ordem inelutável das coisas; Ath. 3, 1 <span class=\"greek\">νόμῳ</span> <span class=\"greek\">φύσεως</span>) <span class=\"greek\">μετήλλαξαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φυσικὴν</span> <span class=\"greek\">χρῆσιν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">φύσιν</span> trocaram a função natural por outra contrária à natureza Ro 1:26 (Diod S 32, 11, 1 <span class=\"greek\">παρὰ</span> <span class=\"greek\">φύσιν</span> <span class=\"greek\">ὁμιλία</span>; Appian, Bell. Civ. 1, 109 §511; Athen. 13, 605d <span class=\"greek\">οἱ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">φύσιν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">Ἀφροδίτῃ</span> <span class=\"greek\">χρώμενοι</span>=os que se entregam a Afrodite contrariamente à natureza; TestNapht 3:4; Philo, Spec. Leg. 3, 39 <span class=\"greek\">ὁ</span> <span class=\"greek\">παιδεραστὴς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">φύσιν</span> <span class=\"greek\">ἡδονὴν</span> <span class=\"greek\">διώκει</span>=um amante de rapazes busca prazer antinatural; Jos., C. Ap. 2, 273; Tat. 3:4; Ath. 26, 2; sobre <span class=\"greek\">φ</span>. como definidora da ordem v. JKube, <span class=\"greek\">ΤΕΧΝΗ</span> und <span class=\"greek\">ΑΡΕΤΗ</span> ’69, especialmente 44–46; sobre a relação com <span class=\"greek\">κτίσι</span> em Paulo, v. OWischmeyer, ZTK 93, ’96, 352–75). <span class=\"greek\">ὅταν</span> <span class=\"greek\">ἔθνη</span> <span class=\"greek\">φύσει</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> <span class=\"greek\">ποιῶσιν</span> quando os gentios cumprem as exigências da lei seguindo a ordem natural (das coisas) Ro 2:14 (cf. Ltzm., Hdb., excurso sobre Ro 2:14–16; mas v. 2 acima). <span class=\"greek\">ἡ</span> <span class=\"greek\">φύσις</span> <span class=\"greek\">διδάσκει</span> <span class=\"greek\">ὑμᾶς</span> 1 Cor 11:14 (Epict. 1, 16, 9f; Plut., Mor. 478d; Synes., Calv. [Baldhead] 14 p. 78c <span class=\"greek\">φύσις</span> assim como <span class=\"greek\">νόμος</span> prescreve cabelos compridos para mulheres, curtos para homens.—Ltzm., Hdb. ad loc.). <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span>, <span class=\"greek\">ὸ̔</span> <span class=\"greek\">κέκτησθε</span> <span class=\"greek\">φύσει</span> <span class=\"greek\">δικαίᾳ</span> o nome que portais em virtude de uma justa ordem natural IEph 1:1 (v. Hdb. ad loc.—<span class=\"greek\">τῇ</span> <span class=\"greek\">φ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">ἀνώφορόν</span> <span class=\"greek\">ἐστιν</span> Did., Gen. 21, 5.—JKleist, trad. ’46, 119 n. 2 sugere ‘disposição natural’).—RGrant, Miracle and Natural Law ’52, 4–18.</p><p class=\"entry-text\">④ entidade como produto da natureza, ser natural, criatura (X., Cyr. 6, 2, 29 <span class=\"greek\">πᾶσα</span> <span class=\"greek\">φύσις</span>=toda criatura; 3 Macc 3:29.—Diod S 2, 49, 4 as plantas são chamadas <span class=\"greek\">φύσεις</span> <span class=\"greek\">καρποφοροῦσαι</span>; 3, 6, 2 <span class=\"greek\">θνητὴ</span> <span class=\"greek\">φ</span>.= uma criatura mortal. Ps.-Callisth. 1, 10, 1 <span class=\"greek\">ἀνθρωπίνη</span> <span class=\"greek\">φ</span>. = uma criatura humana. Pode também significar espécie [X. e outros; 4 Macc 1:20; Philo] e então, por vezes, desaparecer na tradução: Ps.-Pla, Epin. 948d <span class=\"greek\">ἡ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἄστρων</span> <span class=\"greek\">φύσις</span>=os astros; X., Lac. 3, 4 <span class=\"greek\">ἡ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θηλειῶν</span> <span class=\"greek\">φύσις</span>=as mulheres; Aristot., Part. An. 1, 5 <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζῳϊκῆς</span> <span class=\"greek\">φ</span>.=sobre os animais) <span class=\"greek\">πᾶσα</span> <span class=\"greek\">φύσις</span> <span class=\"greek\">θηρίων</span> <span class=\"greek\">κτλ</span>. Js 3:7a. Também provavelmente <span class=\"greek\">ἡ</span> <span class=\"greek\">φ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀνθρωπίνη</span> humanidade 3:7b; v. 2 acima.—Kl. Pauly IV 841–44 (literatura).—DELG s.v. <span class=\"greek\">φύομαι</span> C 6. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυσίωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φυσίωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">φυσιόω</span>; em escritos não bíblicos como termo técnico médico e em Achmes 153, 6; de resto, palavra cristã; Hesych.) lit. ‘estado de inflação/inchaço’, em nossa literatura, presunção, orgulho, soberba <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:20.</a></p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυτεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φυτεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (X., Theophr. e outros; pap [p. ex. POxy 1778, 31], LXX; PsSol 14:4; GrBar 4:8; AscIs 4:3 e Jos., Ant. 3, 281 no sentido de ‘plantio’) aquilo que é plantado, uma planta (Aelian, VH 3, 40; Athen. 5, 207d; OGI 606, 7; Philo, Op. M. 41) em linguagem figurada (PsSol 14:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:13</a>; ITr 11:1; IPhld 3:1 (com Ign. cf. Synes., Prov. 10 p. 100d do homem verdadeiramente bom: <span class=\"greek\">ἔστιν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">φυτὸν</span> <span class=\"greek\">οὐράνιον</span> segundo Pla., Tim. 90a).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυτεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φυτεύω</span> imperf. <span class=\"greek\">ἐφύτευον</span>; 1.º aor. <span class=\"greek\">ἐφύτευσα</span>; perf. 3.ª pl. <span class=\"greek\">πεφύτευκαν</span> Ezk 19:13. Pass.: 1.º aor. <span class=\"greek\">ἐφυτεύθην</span>: perf. <span class=\"greek\">πεφύτευμαι</span>, partic. <span class=\"greek\">πεφυτευμένος</span> (Hom.+; ins, pap, LXX; pseudepígr.; Philo; Jos., Bell. 3, 516, Ant. 11, 50 <span class=\"greek\">ἀμπέλους</span>; Just., D. 110, 4 <span class=\"greek\">φυτευθεῖσα</span> … <span class=\"greek\">ἄμπελος</span>) plantar <span class=\"greek\">τὶ</span> algo. <span class=\"greek\">φυτείαν</span> (v. esse verbete; cf. SibOr 3, 397) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:13</a>; uma árvore (desde Od. 18, 359) Dg 12:3; cf. pass. 12:2, 4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:6</a> (seguido de <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> como X., Oec. 20, 3); B 11:6 (Ps 1:3; seguido de <span class=\"greek\">παρά</span> <span class=\"greek\">τι</span>); varas Hs 8, 2, 6; 8ab; pass. 8, 2, 7; 8, 3, 8; 8, 4, 2. <span class=\"greek\">φυτεύθητι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θαλάσσῃ</span> sê plantada no mar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:6.</a> <span class=\"greek\">ἀμπελῶνα</span> uma vinha (v. <span class=\"greek\">ἀμπελών</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:7</a>; cf. Hs 5, 5, 2; 5, 6, 2. <span class=\"greek\">εἰς</span> <span class=\"greek\">μέρος</span> <span class=\"greek\">τι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀγροῦ</span> <span class=\"greek\">ἐφύτευσεν</span> <span class=\"greek\">ἀμπελῶνα</span> mandou plantar uma vinha em parte de seu campo 5, 2, 2. Abs. (X., Mem. 2, 1, 13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:28</a>; em linguagem figurada Dg 12:6 e da obra do apóstolo (com <span class=\"greek\">ποτίζειν</span>) 1 Cor 3:6–8 (Libanius, Or. 13, 52 vol. II p. 82, 2 F.: <span class=\"greek\">τὸ</span> <span class=\"greek\">καλὸν</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἐφύτευσα</span>, <span class=\"greek\">σὺ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἔθρεψας</span>, <span class=\"greek\">αἱ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πόλεις</span> <span class=\"greek\">δρέπονται</span>).—BHHW III 1441–43.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυτόν, οῦ, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φυτόν</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">φύω</span>; Hom.+) uma planta ApcPt 5:15.—B. 521; BHHW III 1441–43.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φύω</span> (Hom.+) fut. 3.ª pl. <span class=\"greek\">φυήσουσι</span> Is 37:32 (trans.); perf. (intr.) 3.ª pl. <span class=\"greek\">πεφύκασι</span> (Tat. 8, 2), partic., neut. <span class=\"greek\">πεφυκότα</span> 1 Macc 4:38. Pass.: 2.º aor. <span class=\"greek\">ἐφύην</span>, partic. <span class=\"greek\">φυείς</span>, neut. <span class=\"greek\">φυέν</span> (em lugar do antigo 2.º aor. ativo <span class=\"greek\">ἔφυν</span>; 3.ª pl. <span class=\"greek\">ἔφυσαν</span> [Ath. 22, 9]; partic. <span class=\"greek\">φύς</span>, <span class=\"greek\">φύν</span> [Ath., R. 16 p. 68, 9 <span class=\"greek\">φύντας</span> acus. pl.]; inf. <span class=\"greek\">φῦναι</span> [TestSol]). As formas do 2.º aor. pass. aparecem em Hippocr. e em escritores posteriores, incluindo Joseph. (p. ex. Ant. 17, 19; 18, 6; ao lado delas <span class=\"greek\">φύς</span> Ant. 1, 63; 4, 245; <span class=\"greek\">φῦναι</span> 18, 43); CIG 8735.—B-D-F §76, 2; W-S. §13, 11; Mlt-H. 264; Rob. 350. Sobre a LXX v. Thackeray p. 235, 289f.—Em nossa literatura a palavra tem caráter intr., mesmo no pres. ativo (v. B-D-F §309, 2; Rob. 800; SibOr 8, 21) crescer, brotar, lit. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:6,</a> 8. Em linguagem figurada <span class=\"greek\">ῥίζα</span> <span class=\"greek\">πικρίας</span> <span class=\"greek\">ἄνω</span> <span class=\"greek\">φύουσα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:15</a> (Dt 29:17).—DELG s.v. <span class=\"greek\">φύομαι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φωλεός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φωλεός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (Aristot. e outros; TestSol 6:4 D; Jos., Bell. 4, 507) buraco para animais, toca, covil, buraco (Aristot., Plut., Lucian e outros; Herm. Wr. 406, 12 Sc.) de uma toca de raposa (Neptunianus [II d.C.] ed. WGemoll, Progr. Striegau 1884, 27) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.58\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:58</a> (cf. Plut., Tib. Gr. 828 [9, 5] os animais têm <span class=\"greek\">φωλ</span>., mas os que lutam pela Itália estão sem abrigo).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φωνέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φωνέω</span> (<span class=\"greek\">φωνή</span>) imperf. <span class=\"greek\">ἐφώνουν</span>; fut. <span class=\"greek\">φωνήσω</span>; 1.º aor. <span class=\"greek\">ἐφώνησα</span>, pass. <span class=\"greek\">ἐφωνήθην</span> (Hom.+; ins, pap [embora não comum em nenhum dos dois]; LXX; En 14:8; TestSol 12:3 C; TestJob 27:4; GrBar, Philo, Joseph.)</p><p class=\"entry-text\">① produzir um som/tom vocal, frequentemente com referência à intensidade do tom</p><p class=\"entry-text\">ⓐ de animais (Aristot.; Anton. Lib. 7, 8; Is 38:14; Jer 17:11; Zeph 2:14) de um galo: cantar (Aesop, Fab. 225 H.=268 H-H.; 323b H.=84 H-H. III) Mt 26:34, 74f; Mk 14:30, 68 v.l., 72ab; Lk 22:34, 60f; J 13:38; 18:27.</p><p class=\"entry-text\">ⓑ de seres humanos, chamar/clamar, falar em voz alta, dizer com ênfase Lk 8:8; semelhantemente [<span class=\"greek\">ἐφώ</span>]<span class=\"greek\">νει</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">ὦ</span>[<span class=\"greek\">τ</span>]<span class=\"greek\">α</span> <span class=\"greek\">τ</span>[<span class=\"greek\">ῶν</span> <span class=\"greek\">ἀ</span>]<span class=\"greek\">περάντων</span> [<span class=\"greek\">ἀ</span>]<span class=\"greek\">κο</span>[<span class=\"greek\">ύει</span>]<span class=\"greek\">ν</span> <span class=\"greek\">ἀκουέτω</span> (Jesus) clamou: ‘Quem tem ouvidos para ouvir as coisas que não têm limites (ou que nunca terminam) ouça/escute’ Ox 1081, 5f (restauração baseada no SJCh copta 89, 4, v. Borger, GGA 122). <span class=\"greek\">φ</span>. (v.l. <span class=\"greek\">κράξαν</span>) <span class=\"greek\">φωνῇ</span> <span class=\"greek\">μεγάλῃ</span> em alta voz Mk 1:26 (de um espírito maligno numa pessoa); Lk 23:46; Ac 16:28; Rv 14:18 (com dat. da pessoa a quem se destina o chamado; <span class=\"greek\">κραυγῇ</span> <span class=\"greek\">μεγάλῃ</span> *v.l.). <span class=\"greek\">ἐφώνησεν</span> <span class=\"greek\">λέγων</span> Lk 8:54; Ac 16:28; Rv 14:18 (de um anjo que dá uma ordem; v. PGM 13, 148). Também <span class=\"greek\">φωνήσας</span> <span class=\"greek\">εἶπεν</span> Lk 16:24; 23:46.</p><p class=\"entry-text\">② empregar uma atribuição ao falar de uma pessoa, tratar por <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">φωνεῖτέ</span> <span class=\"greek\">με</span>· <span class=\"greek\">ὁ</span> <span class=\"greek\">διδάσκαλος</span> vós me chamais ‘Mestre’ (nom. com art. como voc.; v. B-D-F §143; 147, 3; Rob. 458; 466) J 13:13.</p><p class=\"entry-text\">③ chamar para junto de si, convocar (Tob 5:9) <span class=\"greek\">τινά</span> alguém (Jos., Vi. 172, Ant. 6, 314) <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ἐφώνησεν</span> <span class=\"greek\">αὐτούς</span> Mt 20:32. Cf. 27:47; Mk 3:31 v.l. (em lugar de <span class=\"greek\">καλοῦντες</span>); 9:35; 10:49ab; 15:35; J 1:48; 2:9; 4:16; 11:28a; 18:33; Ac 4:18 D; 9:41; 10:7. <span class=\"greek\">τὸν</span> <span class=\"greek\">Λάζαρον</span> <span class=\"greek\">ἐφώνησεν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μνημείου</span> J 12:17.—<span class=\"greek\">τὰ</span> <span class=\"greek\">πρόβατα</span> <span class=\"greek\">φωνεῖ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὄνομα</span> 10:3 (v. <span class=\"greek\">καλέω</span> 1a). Mandar chamar <span class=\"greek\">τινά</span> alguém Mk 10:49c; Lk 16:2; J 9:18, 24; 11:28b. Pass. <span class=\"greek\">εἶπεν</span> <span class=\"greek\">φωνηθῆναι</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">δούλους</span> disse que os escravos fossem chamados à sua presença Lk 19:15. Com obj. omitido <span class=\"greek\">φωνήσαντες</span> <span class=\"greek\">ἐπυνθάνοντο</span> chamaram (alguém) e perguntaram Ac 10:18.</p><p class=\"entry-text\">④ oferecer hospitalidade mediante convite, convidar <span class=\"greek\">τινά</span> alguém Lk 14:12.—DELG s.v. <span class=\"greek\">φωνή</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φωνή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φωνή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (v. verbete precedente; Hom.+).</p><p class=\"entry-text\">① efeito auditivo, som, tom, ruído, cuja fonte é acrescentada no gen.: de instrumentos musicais (Pla., Rep. 3, 397a <span class=\"greek\">ὀργάνων</span>; Eur., Tro. 127 <span class=\"greek\">συρίγγων</span>; Plut., Mor. 713c <span class=\"greek\">ψαλτηρίου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αὐλοῦ</span>; Aristoxenus, Fgm. 6; Paus. Attic. <span class=\"greek\">α</span>, 169; Ex 19:16, Is 18:3 e PsSol 8:1 <span class=\"greek\">σάλπιγγος</span>; cf. ParJer 3:2; Is 24:8 <span class=\"greek\">κιθάρας</span>; Aristobul. em Eus., PE 8, 10, 13=p. 144, 94f Holladay) <span class=\"greek\">σάλπιγγος</span> Mt 24:31 v.l.; D 16:6. <span class=\"greek\">φωναὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σάλπιγγος</span> toques da trombeta Rv 8:13b; ou daqueles que os tocam <span class=\"greek\">κιθαρῳδῶν</span> 14:2d; 18:22a; cf. 10:7. Do ruído produzido por uma mó 18:22b. De um clamor produzido por uma multidão de pessoas <span class=\"greek\">φωνὴ</span> <span class=\"greek\">ὄχλου</span> <span class=\"greek\">πολλοῦ</span> 19:1, 6a (cf. Da 10:6 Theod.; também <span class=\"greek\">λαοῦ</span> <span class=\"greek\">πολλοῦ</span> PsSol 8:2). Do som causado por palavras pronunciadas (Da 10:9; Just., D. 131, 2 <span class=\"greek\">μηδὲ</span> <span class=\"greek\">μέχρι</span> <span class=\"greek\">φωνῆς</span>) <span class=\"greek\">ἡ</span> <span class=\"greek\">φωνὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀσπασμοῦ</span> <span class=\"greek\">σου</span> Lk 1:44. <span class=\"greek\">φωνὴ</span> <span class=\"greek\">ῥημάτων</span> som de palavras Hb 12:19. Cf. 1 Cl 27:7 (Ps 18:4). <span class=\"greek\">ἔσομαι</span> <span class=\"greek\">φωνή</span> serei apenas um som sem significado (em contraste com Inácio funcionando como um <span class=\"greek\">λόγος</span> <span class=\"greek\">θεοῦ</span> [=expressão significativa de Deus] se seus adeptos se abstiverem de súplicas em seu favor) IRo 2:1 (v. <span class=\"greek\">ἠχώ</span>). Abs. do som produzido por um lamento de tristeza (cf. TestJob 40:9; TestIss 1:4) Mt 2:18 (Jer 38:15). <span class=\"greek\">μεγάλη</span> <span class=\"greek\">φωνὴ</span> <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανῷ</span> GPt 9:35.—Dos instrumentos musicais diz-se que <span class=\"greek\">φωνὴν</span> <span class=\"greek\">διδόναι</span> produzem som (em referência à mera capacidade sonora, em contraste com notas distinguíveis) 1 Cor 14:7f.—Em Rv temos <span class=\"greek\">ἀστραπαὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φωναὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βρονταί</span> (cf. Ex 19:16) 4:5; 8:5; 11:19; 16:18 (pensar-se-á aqui em certos outros sons da natureza além do trovão, como p. ex. o rugido da tempestade? Em Ex 19:16 <span class=\"greek\">φωναὶ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀστραπαί</span> são certamente trovão e relâmpago. Mas em Ex 9:23, 28; 1 Km 12:18 o sentido de <span class=\"greek\">φωναί</span> permanece obscuro. Cf. também Esth 1:1d <span class=\"greek\">φωναί</span>, <span class=\"greek\">βρονταί</span>).—Frequentemente em linguagem figurada: do som do vento J 3:8; cf. Ac 2:6. De estrondo de trovão (1 Km 7:10; GrBar 6:13) Rv 6:1; 14:2c; 19:6c. De rugido de águas (Ezk 1:24b) 1:15b; 14:2b; 19:6b. Do zumbido de asas (Ezk 1:24a) 9:9a. Do estrépito de carros 9:9 b (cf. Ezk 3:13; 26:10).</p><p class=\"entry-text\">② a faculdade de emissão vocal, voz (Tat. 15:3 <span class=\"greek\">προύχει</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θηρίων</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἔναρθον</span> <span class=\"greek\">φωνήν</span>=a humanidade supera os animais na emissão articulada da voz)</p><p class=\"entry-text\">ⓐ geralmente quanto ao aspecto sonoro: qualquer forma de fala ou outra emissão da voz pode ocorrer <span class=\"greek\">μετὰ</span> <span class=\"greek\">φωνῆς</span> <span class=\"greek\">μεγάλης</span> Lk 17:15; <span class=\"greek\">ἐν</span> <span class=\"greek\">φωνῇ</span> <span class=\"greek\">μεγάλῃ</span> Rv 5:2; 14:7, 9; sobretudo <span class=\"greek\">φωνῇ</span> <span class=\"greek\">μεγάλῃ</span> (TestAbr A 5 p. 82, 20f [Stone p. 12]; ParJer 2:2; Achilles Tat. 8, 1, 1; SibOr 3, 669; 5, 63) Mt 27:46, 50; Mk 1:26; 5:7; 15:34; Lk 1:42 v.l. (v. <span class=\"greek\">κραυγή</span> 1b); 4:33; 8:28; 19:37; J 11:43; Ac 7:57, 60; 8:7; Rv 6:10; 7:2, 10 e outros lugares; IPhld 7:1a. <span class=\"greek\">μεγάλῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">φωνῃ</span> (Diod S 1, 70, 5; 8, 23, 3; Lucian, Hist. Conscr. 1, Tim. 9; ParJer 9:8; Jos., Bell. 6, 188) Ac 14:10 v.l. 26:24; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἰσχυρᾷ</span> <span class=\"greek\">φωνῇ</span> Rv 18:2. <span class=\"greek\">ἐν</span> <span class=\"greek\">φωνῇ</span> <span class=\"greek\">μιᾷ</span> IEph 4:2; <span class=\"greek\">μιᾷ</span> <span class=\"greek\">φ</span>. (Pla., Laws 1, 634e; Diod S 11, 9, 3; 11, 26, 6; 19, 81, 2; Ael. Aristid. 24, 4 K.=44 p. 825 D.; Lucian, Nigr. 14) ApcPt 5:19.—<span class=\"greek\">αἴρειν</span> <span class=\"greek\">φωνήν</span> (<span class=\"greek\">αἴρω</span> 1b) Lk 17:13; <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> Ac 4:24. <span class=\"greek\">ἐπαίρειν</span> <span class=\"greek\">φωνήν</span> (ParJer 9:14; v. <span class=\"greek\">ἐπαίρω</span> 1) Lk 11:27; Ac 2:14; 14:11; 22:22; AcPl Ha 6, 33. <span class=\"greek\">ἀκούειν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">φωνῆς</span> <span class=\"greek\">τινος</span> ouvir alguém falar ou chamar (TestAbr B 3 p. 107, 10 [Stone p. 62]; TestJob 42:3; TestJos 9:4; ParJer 3:10) J 5:25, 28; 10:3; Hb 3:7, 15; 4:7 (os três últimos Ps 94:7); com negativa e acus. (<span class=\"greek\">φωνήν</span>) Mt 12:19 (cf. Is 42:2); J 5:37. A mesma expressão=dar ouvidos à fala ou chamado de alguém, seguir alguém (Gen 3:17) 10:16, 27; 18:37; Rv 3:20; B 8:7; cf. 9:2 (v. Ex 15:26).—(<span class=\"greek\">ἡ</span>) <span class=\"greek\">φωνὴ</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">νυμφίου</span> (cf. Jer 25:10) J 3:29 (cf. Arrian, Cyneg. 17, 1 os cães <span class=\"greek\">χαίρουσιν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φωνὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δεσπότου</span> <span class=\"greek\">γνωρίζουσαι</span>); Rv 18:23.</p><p class=\"entry-text\">ⓑ voz enquanto varia de indivíduo para indivíduo ou de um estado de ânimo para outro (X., An. 2, 6, 9; Gen 27:22; Tat. 5:2) <span class=\"greek\">ἐπιγνοῦσα</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φωνὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Πέτρου</span> Ac 12:14. Cf. J 10:4f (v. Ael. Aristid. 46 p. 320, cavalos). <span class=\"greek\">ἤθελον</span> <span class=\"greek\">ἀλλάξαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φωνήν</span> <span class=\"greek\">μου</span> Gal 4:20 (<span class=\"greek\">ἀλλάσσω</span> 1; <span class=\"greek\">φωνή</span>=tom: Diod. S 8, 5, 4 <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">φωνήν</span>=toda variação de tom; Artem. 4, 56 p. 235, 15).</p><p class=\"entry-text\">ⓒ aquilo a que a voz dá expressão: chamado, grito, clamor, declaração em voz alta ou solene (Sb 7251, 21 [III/IV d.C.]=ordem, mandamento) <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ἀφεὶς</span> <span class=\"greek\">φωνὴν</span> <span class=\"greek\">μεγάλην</span> Mk 15:37. <span class=\"greek\">φωνὴ</span> <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">μία</span> ergueu-se um único clamor Ac 19:34 (cf. Jos., Vi. 133). Cf. 22:14; 24:21. Pl. (Ael. Aristid. 52, 3 K.=28 p. 551 D.: <span class=\"greek\">ἦσαν</span> <span class=\"greek\">φωναί</span>; Jos., Vi. 231, Ant. 15, 52) <span class=\"greek\">φωναὶ</span> <span class=\"greek\">μεγάλαι</span> grandes clamores Lk 23:23a; cf. 23b. <span class=\"greek\">ἐλάλησαν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">βρονταὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">φωνάς</span> os trovões fizeram ressoar seus estrondos Rv 10:3b. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">φωνὴ</span> (D <span class=\"greek\">φωναί</span>) <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀνθρώπου</span> (isto é) a voz de um deus e não de um simples mortal Ac 12:22 (Just., D. 119, 6 <span class=\"greek\">τῇ</span> <span class=\"greek\">φωνῇ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; cf. 21, 1 <span class=\"greek\">αἱ</span> <span class=\"greek\">φωναὶ</span> <span class=\"greek\">αὐτοῦ</span>; Plut., Mor. 567f: uma <span class=\"greek\">φωνή</span> divina ressoa de um <span class=\"greek\">φῶς</span> <span class=\"greek\">μέγα</span> que aparece repentinamente; Ael. Aristid. 45 p. 11 D.: <span class=\"greek\">Πυθίας</span> <span class=\"greek\">φωνή</span>; Epict. 3, 23, 20 <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">φωναὶ</span> <span class=\"greek\">φιλοσόφου</span>; 3, 22, 50; Biogr. p. 454 pessoas recebiam os ditos de Hippocr. <span class=\"greek\">ὡς</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">φωνὰς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀνθρωπίνου</span> <span class=\"greek\">προελθούσας</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">στόματος</span>). <span class=\"greek\">φωνὴ</span> <span class=\"greek\">ἐνεχθεῖσα</span> <span class=\"greek\">αὐτῷ</span> uma declaração (foi) transmitida a ele 2 Pt 1:17; cf. v. 18. Também de ditos nas Escrituras <span class=\"greek\">αἱ</span> <span class=\"greek\">φωναὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προφητῶν</span> Ac 13:27 (Ath. 9, 1; cf. Diod S 19, 1, 4 <span class=\"greek\">ἡ</span> <span class=\"greek\">Σόλωνος</span> <span class=\"greek\">φωνή</span>; 20, 30, 2 <span class=\"greek\">τῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μάντεως</span> [=<span class=\"greek\">τοῦ</span> <span class=\"greek\">δαιμονίου</span>] <span class=\"greek\">φωνῆς</span>; Diog. L. 8, 14 ditos de Pitágoras). Da tradição apostólica <span class=\"greek\">τὰ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">ζώσης</span> <span class=\"greek\">φωνῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μενούσης</span> Papias (2:4) (v. <span class=\"greek\">ζάω</span>, final; sobre a ‘voz viva’ de Papias v. ABaum, NTS 44, ’98, 144–51).</p><p class=\"entry-text\">ⓓ Em conformidade com o uso do AT e judaico em geral (v. Bousset, Rel.3 315. O <span class=\"greek\">δαιμόνιον</span> socrático [=<span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> Ep. 1, 7] é chamado <span class=\"greek\">ἡ</span> <span class=\"greek\">φωνή</span>: Socrat., Ep. 1, 9 [p. 222, 34 Malherbe] <span class=\"greek\">τὸ</span> <span class=\"greek\">δαιμόνιόν</span> <span class=\"greek\">μοι</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">φωνή</span>, <span class=\"greek\">γέγονεν</span>, cf. Pla., Apol. 31d) ‘a voz’ frequentemente fala, embora o locutor (celestial) nem apareça nem seja mencionado (cf. PGM 3, 119 <span class=\"greek\">ἐξορκίζω</span> <span class=\"greek\">σε</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἑβραικῆς</span> <span class=\"greek\">φωνῆς</span>.—Na maioria dos casos a voz divina é diferenciada da divindade: Theopompus [IV a.C.]: 115 Fgm. 69 Jac. [em Diog. L. 1, 115] quando Epimênides deseja construir <span class=\"greek\">τὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Νυμφῶν</span> <span class=\"greek\">ἱερόν</span>: <span class=\"greek\">ῥαγῆναι</span> <span class=\"greek\">φωνὴν</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span> ‘<span class=\"greek\">Ἐπιμενίδη</span>, <span class=\"greek\">μὴ</span> <span class=\"greek\">Νυμφῶν</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">Διός</span>’=[quando E. construía] um santuário para as Ninfas: uma voz clamou do céu: “Epimênides! Não para as Ninfas, mas para Zeus!”; Plut., Mor. 355e; 775b; Oenomaus em Eus., PE 5, 28, 2 Licurgo recebe as leis <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">φωνῆς</span> em Delfos; Artapanus; 726 Fgm. 3, 21 Jac. [em Eus., PE 9, 27, 21]; Jos., Ant. 1, 185 <span class=\"greek\">φ</span>. <span class=\"greek\">θεία</span> <span class=\"greek\">παρῆν</span>; 3, 90 <span class=\"greek\">φ</span>. <span class=\"greek\">ὑψόθεν</span>; cf. 2, 267) <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">φωνὴ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">οὐρανῶν</span> <span class=\"greek\">λέγουσα</span> (sobre a voz do céu v. a literatura s.v. <span class=\"greek\">βαπτίζω</span> 2a; também JKosnetter, D. Taufe Jesu ’36, especialmente 140–90, e FDölger, Ac V/3, ’36, 218–23) Mt 3:17; cf. 17:5. <span class=\"greek\">ἦλθεν</span> <span class=\"greek\">φ</span>. (<span class=\"greek\">ἐκ</span>) Mk 9:7 v.l.; J 12:28; 30 v.l. (TestAbr A 10 p. 88, 15 [Stone p. 24] e outros lugares; cf. Ps. Callisth, 1, 45, 2f <span class=\"greek\">ἦλθεν</span> <span class=\"greek\">φωνὴ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀδύτου</span> o dito divino segue em discurso direto). <span class=\"greek\">ἐξῆλθεν</span> <span class=\"greek\">φ</span>. Rv 16:17 (<span class=\"greek\">ἐκ</span>); 19:5 (<span class=\"greek\">ἀπό</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θρόνου</span>). <span class=\"greek\">γίνεται</span> (<span class=\"greek\">ἐγένετο</span>) <span class=\"greek\">φ</span>. (<span class=\"greek\">ἐκ</span>: Plut., Agis et Cleom. 807 [28, 3]: <span class=\"greek\">φωνὴν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱεροῦ</span> <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">φράζουσαν</span>; Ael. Aristid. 40, 22 K.=5 p. 62 D.: <span class=\"greek\">φωνῆς</span> <span class=\"greek\">θείας</span> <span class=\"greek\">γενομένης</span> … <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μητρῴου</span> [=templo da Mãe dos Deuses]) Mk 1:11; 9:7; Lk 3:22; 9:35f; J 12:30 (v.l. <span class=\"greek\">ἦλθεν</span>; v. acima); Ac 10:13, 15 (ambos <span class=\"greek\">πρὸς</span> <span class=\"greek\">αὐτόν</span>); MPol 9:1a; GEb 18, 37 (verbo de origem subentendido), cf. ibid. ln. 38; <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">φ</span>. <span class=\"greek\">κυρίου</span> Ac 7:31 (cf. Jos., Vi. 259 <span class=\"greek\">ἐγένοντο</span> <span class=\"greek\">φωναί</span>). <span class=\"greek\">ἀπεκρίθη</span> <span class=\"greek\">φ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανοῦ</span> 11:9; <span class=\"greek\">ἦχος</span> <span class=\"greek\">φωνῆς</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἀπεκρίθη</span> Hv 4, 1, 4. <span class=\"greek\">ἀκούειν</span> <span class=\"greek\">φωνήν</span> ouvir uma voz (também com acréscimos como <span class=\"greek\">λέγουσαν</span>, <span class=\"greek\">ἐκ</span> com gen. de lugar, <span class=\"greek\">μεγάλην</span>, gen. do locutor) Ac 9:4; 22:9; 26:14; Rv 6:6f; 9:13; 10:4, 8; 12:10; 14:2; 18:4; MPol 9:1b; EpilMosq 4; <span class=\"greek\">φωνῆς</span> com o mesmo sentido (com acréscimos correspondentes) Ac 9:7; 11:7; 22:7 (MMeyer, The Light and Voice on the Damascus Road: Forum 2, ’86, 27–35 [Nag Hammadi pp. 30–32]); Rv 11:12; 14:13; 16:1; 21:3; GPt 10:41. Paulo fala <span class=\"greek\">διὰ</span> <span class=\"greek\">φωνῆς</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span> AcPl Ha 11, 5.</p><p class=\"entry-text\">ⓔ casos especiais: <span class=\"greek\">ἐπέστρεψα</span> <span class=\"greek\">βλέπειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φωνὴν</span> <span class=\"greek\">ἥτις</span> <span class=\"greek\">ἐλάλει</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">ἐμοῦ</span> voltei-me para ver (a quem pertencia) a voz que falava comigo Rv 1, 12 (cf. X., Hell. 5, 1, 22 <span class=\"greek\">σκεψόμενοι</span> <span class=\"greek\">τίς</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κραυγή</span>; Aesop 248b H.=141 P.=146 H-H. <span class=\"greek\">ἐπεστράφη</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φ</span>.). <span class=\"greek\">φ</span>. <span class=\"greek\">βοῶντος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐρήμῳ</span> (é) a voz de alguém que clama no deserto (Is 40:3; cf. En 9:2; Jos., Bell. 6, 301) Mt 3:3; Mk 1:3; Lk 3:4. Referindo-se a Is 40:3, João Batista aplica suas palavras a si mesmo J 1:23 a voz de alguém que clama no deserto (Ael. Aristid. 49, 5 K.=25 p. 489 D.: <span class=\"greek\">φ</span>. <span class=\"greek\">λέγοντός</span> <span class=\"greek\">του</span> ‘<span class=\"greek\">τεθεράπευσαι</span>’; Ps.-Pla., Axioch. 1 p. 364a <span class=\"greek\">φωνὴ</span> <span class=\"greek\">βοῶντός</span> <span class=\"greek\">του</span>).—B 9:3.</p><p class=\"entry-text\">③ código verbal compartilhado por uma comunidade para exprimir ideias e sentimentos, língua (Aeschyl., Hdt. e outros; Cebes 33, 6; Aelian, VH 12, 48; Herodian 5, 3, 4; Diog. L. 8, 3; SEG VIII, 548, 17 [I a.C.]; PLond I, 77, 13 p. 232 [cristão VIII d.C.]; PGM 12, 188 <span class=\"greek\">πᾶσα</span> <span class=\"greek\">γλῶσσα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">φωνή</span>; Gen 11:1; Dt 28:49; 2 Macc 7:8, 21, 27; 4 Macc 12:7; Jos., C. Ap. 1, 1; 50; 73 e outros lugares; Just., A I, 31, 1; Tat. 37, 1; Mel., P. 29, 199) 1 Cor 14:10f; 2 Pt 2:16 (um animal com <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">φ</span>. como Appian, Bell. Civ. 4:4 §14 <span class=\"greek\">βοῦς</span> <span class=\"greek\">φωνὴν</span> <span class=\"greek\">ἀφῆκεν</span> <span class=\"greek\">ἀνθρώπου</span>; escólio a Appolon. Rhod. 2, 1146 <span class=\"greek\">ὁ</span> <span class=\"greek\">κριὸς</span> <span class=\"greek\">ἀνθρωπίνῃ</span> <span class=\"greek\">χρησάμενος</span> <span class=\"greek\">φωνῇ</span>; semelhantemente TestAbr A 3 p. 79, 19 [Stone p. 6]; semelhantemente TestAbr B 3 p. 107, 10 [St. p. 62] uma árvore; ParJer 7:2 uma águia; Philo, Op. M. 156); Dg 5:1. <span class=\"greek\">ὁ</span> <span class=\"greek\">λέων</span> <span class=\"greek\">εἶπεν</span> <span class=\"greek\">μιᾷ</span> <span class=\"greek\">φωνῇ</span> AcPlHa 5, 4 (sobre a probabilidade de que <span class=\"greek\">μια</span> tenha sido lido erroneamente por <span class=\"greek\">θεια</span> v. a nota do editor, p. 41, 4).—B. 1248; 1260. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φῶς, φωτός, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φῶς</span>, <span class=\"greek\">φωτός</span>, <span class=\"greek\">τό</span> (Trag.+ [em Hom. <span class=\"greek\">φάος</span> ou <span class=\"greek\">φόως</span>]; empréstimo na literatura rabínica) ‘luz’</p><p class=\"entry-text\">① luz em contraste com trevas, luz</p><p class=\"entry-text\">ⓐ no domínio físico <span class=\"greek\">καθόλου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">βλέπειν</span> (de Judas) Papias (3:2).—Oposto a <span class=\"greek\">σκότος</span>, como Job 18:18; En 104:8; PGM 5, 101; 7, 262; 13, 335; Theoph. Ant. 1, 2 (p. 60, 7) 2 Cor 4:6 (cf. Gen 1:3ff); 6:14. Não presente à noite J 11:10. <span class=\"greek\">λευκὸς</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φ</span>. Mt 17:2. <span class=\"greek\">νεφέλη</span> <span class=\"greek\">φωτός</span> uma nuvem luminosa v. 5 v.l. (TestAbr A 9 p. 87, 12 [Stone p. 22]). Da luz do sol (<span class=\"greek\">φ</span>. <span class=\"greek\">ἡλίου</span>: Dio Chrys. 57 [74], 20 de Eur., Hippol. 617; Ael. Aristid. 45, 29 K.=8 p. 95 D; ApcZeph; Just., D. 128, 4; <span class=\"greek\">τὸ</span> <span class=\"greek\">φ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἡλίου</span> Theoph. Ant. 1, 2 [p. 60, 16]) Rv 22:5b; de uma estrela prodigiosa IEph 19:2ab. Da luz de uma lâmpada (Jer 25:10; Jos., Ant. 12, 319) Lk 8:16; 11:33 (v.l. <span class=\"greek\">φέγγος</span>); J 5:35 (em linguagem figurada); Rv 18:23; 22:5a. Luz de uma fonte transcendente (Ael. Aristid. 49, 46 K.=p. 500, 17 D. <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἴσιδος</span>; Marinus, Vi. Procli 23: um halo de luz em torno da cabeça de Proclo impele o observador à <span class=\"greek\">προσκύνησις</span>): um anjo Ac 12:7; 2 Cor 11:14 (aqui <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">φωτός</span> [cf. 1QS 3:20] é um mensageiro do mundo da luz em contraste com Satanás); da experiência de conversão de Paulo Ac 9:3; 22:6 (ambos com <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span>, como X., Cyr. 4, 2, 15; Dio Chrys. 11 [12], 29), 9, 11; 26:13 (<span class=\"greek\">οὐρανόθεν</span>); a cidade celestial Rv 21:24 (v. também b<span class=\"greek\">α</span> abaixo). <span class=\"greek\">ἐφάνη</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">μέγα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σπηλαίῳ</span> uma luz brilhante apareceu na caverna GJs 19:2, seguido de <span class=\"greek\">φῶς</span> <span class=\"greek\">ἐκεῖνο</span> <span class=\"greek\">ὑπεστέλλετο</span> aquela luz foi desaparecendo. <span class=\"greek\">ἦν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρος</span> <span class=\"greek\">ἐκεῖνο</span> <span class=\"greek\">διαφαίνων</span> (pap=<span class=\"greek\">διαφαῖνον</span>) <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">φ</span>. aquele monte irradiava uma luz para ela GJs 22:3.—Em linguagem figurada: (<span class=\"greek\">εἰς</span> <span class=\"greek\">φ</span>. <span class=\"greek\">ἐλθεῖν</span>=‘tornar-se manifesto’ Hippol., Ref. 4, 28, 4) <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φωτί</span> abertamente, publicamente (<span class=\"greek\">φ</span>. de ‘o espaço aberto’ X., Ages. 9, 1.—Oposto a <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σκοτίᾳ</span>) Mt 10:27; Lk 12:3 (Proverbia Aesopi 104 P.: <span class=\"greek\">ἅπερ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">νυκτὶ</span> <span class=\"greek\">καλύπτεται</span>, <span class=\"greek\">ταῦτα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">λαληθέντα</span> … ‘aquilo que se oculta à noite é falado à luz’). De quem pratica o mal diz-se: <span class=\"greek\">μισεῖ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔρχεται</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> J 3:20 (cf. Eur., Iph. T. 1026 <span class=\"greek\">κλεπτῶν</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">νύξ</span>, <span class=\"greek\">τῆς</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">ἀληθείας</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span>=a noite é dos ladrões, a luz é da verdade; Plut., Mor. 82b, Contra Volupt. em Stob., Anthol. 3, 6, 33 vol. III 299 H.; Philo, De Jos. 68, Spec. Leg. 1, 319–23; TestNapht 2:10).</p><p class=\"entry-text\">ⓑ em sentido transcendente</p><p class=\"entry-text\"><span class=\"greek\">α</span>. as passagens da parte central de 1a acima mostram que a luz é o elemento e a esfera do divino (Ael. Aristid. 28, 114 K.=49 p. 528 D.: <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">φῶς</span>; SibOr 3, 787 <span class=\"greek\">ἀθάνατον</span> <span class=\"greek\">φ</span>.; Tat. 13, 2 <span class=\"greek\">λόγος</span> … <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">φ</span>.—Iren. 1, 4, 1 [Harv. I 32, 1]). Deus é denominado <span class=\"greek\">φῶς</span> <span class=\"greek\">οἰκῶν</span> <span class=\"greek\">ἀπρόσιτον</span> 1 Ti 6:16 (Plut., Pericl. 173 [39, 2] os deuses habitam <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">ἀσάλευτον</span> <span class=\"greek\">φωτὶ</span> <span class=\"greek\">καθαρωτάτῳ</span> <span class=\"greek\">περιλαμπόμενον</span>, Mor. 567f: a <span class=\"greek\">φωνή</span> divina procede de um <span class=\"greek\">φῶς</span> <span class=\"greek\">μέγα</span> que subitamente resplandece), ou diz-se que Deus habita <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φωτί</span> 1J 1:7b. De fato, Deus é descrito pura e simplesmente como luz <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">ἐστιν</span> v. 5 (Philo, Somn. 1, 75; cf. TestJob 4:1 <span class=\"greek\">εἶπεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span>; ParJer 6:12; Ath. 31, 3 <span class=\"greek\">πάντα</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ὄντα</span>.—OSchaefer, StKr 105, ’33, 467–76). Cf. Dg 9:6. Igualmente o Redentor divino (ParJer 9:14 <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">αἰώνων</span> <span class=\"greek\">πάντων</span>) no quarto Evangelho: J 1:7–9 (FAuer, Wie ist J 1:9 zu verstehen?: ThGl 28, ’36, 397–407); 12:35ab, 36ab (para 1J 2:8 v. <span class=\"greek\">β</span>; sobre a divindade como luz v. RCharles, The Book of Enoch 1912, 71f; GWetter, Phōs [<span class=\"greek\">ΦΩΣ</span>] 1915. V. também MDibelius, Die Vorstellung v. göttl. Licht: Deutsche Literaturzeitung 36, 1915, 1469–83 e MNilsson, GGA 1916, 49ff; FDölger, Die Sonne der Gerechtigkeit 1918, Sol Salutis 1920; WBousset, Kyrios Christos 2, 1921, 173; 174, 2 e 3; HJonas, Gnosis u. spätantiker Geist I ’34; Dodd 133–36; 183–87 e outros lugares; EGoodenough, By Light, Light: The Mystic Gospel of Hellenistic Judaism ’35; RBultmann, Z. Gesch. der Lichtsymbolik im Altertum: Philol 97, ’48, 1–36; 1QH 4:6; 18:29; BGU 597, 33 [I d.C.]). Jesus chama a si mesmo <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> J 8:12a; 9:5; 12:46; cf. 3:19a (Mel., P. 103, 795; Wetter, ‘Ich bin das Licht der Welt’: Beiträge zur Religionswissenschaft I/2, 1914, 171ff), e é chamado <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> 1:4 (Ael. Aristid. 45, 33 K.=8 p. 97 D.: Sarápis como <span class=\"greek\">κοινὸν</span> <span class=\"greek\">ἄπασιν</span> <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">φῶς</span>; hino a Anúbis de Cios [IAndrosIsis, p. 139] 7: Ísis como <span class=\"greek\">φῶς</span> <span class=\"greek\">πᾶσι</span> <span class=\"greek\">βροτοῖσι</span>). Seu próprio ser é luz e vida (<span class=\"greek\">ζωή</span> 2a<span class=\"greek\">β</span>; v. JWeisengoff, CBQ 8, ’46, 448–51) 1:4. Cf. também v. 5; 3:19b, 21; Lk 2:32 (Jesus é um <span class=\"greek\">φῶς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀποκάλυψιν</span> <span class=\"greek\">ἐθνῶν</span>).—FDölger, Lumen Christi: Ac V/1, ’35, 1–43. O mártir <span class=\"greek\">καθαρὸν</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">λαμβάνει</span> recebe a luz pura do céu IRo 6:2.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. a luz, que ilumina o espírito e a alma dos seres humanos (OdeSol 11:19 <span class=\"greek\">μεταβληθέντες</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">σκότους</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span>; JosAs 15:13 <span class=\"greek\">ἀναγαγεῖν</span> <span class=\"greek\">με</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span>; Mel., P. 68, 491 <span class=\"greek\">ῥυσάμενος</span> … <span class=\"greek\">ἐκ</span> <span class=\"greek\">σκότους</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φῶς</span>; Philosoph. Max. 499, 39 <span class=\"greek\">σωφροσύνη</span> … <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">ἐστιν</span>), é geralmente o elemento em que vive a pessoa redimida, rica em bênçãos exteriores e interiores (En 5:6 <span class=\"greek\">σωτηρία</span>, <span class=\"greek\">φῶς</span> <span class=\"greek\">ἀγαθόν</span>; v. 8 <span class=\"greek\">φ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">χάρις</span>; PsSol 3:12 <span class=\"greek\">ἡ</span> <span class=\"greek\">ζωὴ</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">φωτὶ</span> <span class=\"greek\">κυρίου</span>): <span class=\"greek\">τότε</span> <span class=\"greek\">ῤαγήσεται</span> <span class=\"greek\">πρώϊμον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">σου</span> então tua luz irromperá de manhã cedo B 3:4 (Is 58:8; v. <span class=\"greek\">πρόϊμος</span>, final). De Deus <span class=\"greek\">δεῖξαι</span> <span class=\"greek\">αὐτῷ</span> (servo de Deus) <span class=\"greek\">φῶς</span> 1 Cl 16:12 (Is 53:11); da salvação messiânica, do evangelho etc. (oposto a <span class=\"greek\">σκοτία</span>, <span class=\"greek\">σκότος</span>) Mt 4:16ab; AcPl Ha 8, 32f (Is 9:1ab; cf. Lucian, Nigr. 4 <span class=\"greek\">ἔχαιρον</span> <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ζοφεροῦ</span> <span class=\"greek\">ἀέρος</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">μέγα</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">ἀναβλέπων</span> ‘alegrei-me, como se erguesse os olhos de uma atmosfera sombria para uma luz brilhante’); Ac 26:18; Eph 5:13; Col 1:12; 1 Pt 2:9; 1 Cl 36:2; 59:2; 2 Cl 1:4. <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> (cf. 1QS 3:7) J 8:12b. <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀληθινόν</span> (ParJer 9:3 <span class=\"greek\">φ</span>. <span class=\"greek\">ἀληθινόν</span>; cf. <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span> <span class=\"greek\">φ</span>. Did., Gen. 87, 23f; Orig., C. Cels. 5, 13, 20; dito dos pitagóricos: WienerStud 8, 1886 p. 280 n.º 118 em contraste com <span class=\"greek\">σκότος</span>; cf. TestJob 43:6 <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκότους</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φωτός</span> [de Eliú]) 1J 2:8, cf. J 1:9 (v. <span class=\"greek\">α</span> acima). <span class=\"greek\">φῶς</span> <span class=\"greek\">καταγγέλλειν</span> Ac 26:23. Estar cheio da verdade cristã significa <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φωτὶ</span> <span class=\"greek\">περιπατεῖν</span> 1J 1:7a, <span class=\"greek\">εἶναι</span> 2:9, <span class=\"greek\">μένειν</span> v. 10. Tais pessoas são chamadas <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φωτός</span> Lk 16:8; J 12:36c (cf. 1QS 1:9 et passim); 1 Th 5:5; <span class=\"greek\">τέκνα</span> <span class=\"greek\">φωτός</span> Eph 5:8b (ESelwyn, 1 Pt ’46, 375–82; KKuhn, NTS 7, ’61, 339: 1QS 3:20; 5:9, 10); <span class=\"greek\">τέκνα</span> <span class=\"greek\">φωτὸς</span> <span class=\"greek\">ἀληθείας</span> IPhld 2:1 (Porphyr., Ep. ad Marcellam 20 <span class=\"greek\">φῶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span>; Simplicius p. 88, 3; 138, 30 Düb. <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span> <span class=\"greek\">φῶς</span>). Revestem-se de <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅπλα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φωτός</span> Ro 13:12, percorrem a <span class=\"greek\">ὁδὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φωτός</span> B 18:1; 19:1, 12, e produzem o <span class=\"greek\">καρπὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φωτός</span> Eph 5:9. A leitura <span class=\"greek\">τ̣ο̣</span> [<span class=\"greek\">φω</span>]<span class=\"greek\">ς</span> Ox 1081, 29 é mais bem restaurada, segundo o SJCh copta, como <span class=\"greek\">τέλος</span> (v. esse verbete 1).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. portadores ou transmissores dessa espécie de luz (<span class=\"greek\">φῶς</span> de pessoas: Od. 16, 23; Anacr. 51 Diehl [32 Page; 124 Bergk] <span class=\"greek\">φάος</span> <span class=\"greek\">Ἑλλήνων</span>; Pind., I. 2, 17; Trag.; Biogr. p. 453 Hipócrates como <span class=\"greek\">ἀστήρ</span> e <span class=\"greek\">φῶς</span> da arte de curar; TestJob 53:3 Jó como <span class=\"greek\">φῶς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τυφλῶν</span>; SIG 1238, 2 [c. 160 d.C.] <span class=\"greek\">Φήγιλλα</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκίας</span>) Is 49:6 <span class=\"greek\">φῶς</span> <span class=\"greek\">ἐθνῶν</span> é referido a Paulo e Barnabé Ac 13:47, e a Cristo B 14:8 (como Just., D. 65, 7); cf. 14:7 (Is 42:6) e cf. b<span class=\"greek\">α</span> acima. O <span class=\"greek\">Ἰουδαῖος</span> considera-se um <span class=\"greek\">φῶς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σκότει</span> Ro 2:19. Os discípulos de Jesus são <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> Mt 5:14; cf. v. 16.—Sobre Is 49:6 v. HOrlinsky, The 75th Anniv. Vol. of the JQR ’67, 409–28.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. por metonímia, aquele que é iluminado ou cheio de tal luz, ou que está nela Eph 5:8a (v. 1b<span class=\"greek\">β</span> acima).—Sobre o dualismo de luz e trevas etc., v. textos hebraicos nos manuscritos do mar Morto: KKuhn, ZTK 47, ’50, 192–211; WBrownlee, Excerpts fr. theTransl. of the Dead Sea Manual of Discipline: BASOR n.º 121, ’51, 8–13; HPreisker, TLZ 77, ’52, 673–78; CHowie, The Cosmic Struggle: Int 8, ’54, 206–17.</p><p class=\"entry-text\">② aquilo que dá/porta luz, tocha, lâmpada, lanterna etc. (X., Hell. 5, 1, 8 <span class=\"greek\">φῶς</span> <span class=\"greek\">ἔχειν</span>; Musaeus v. 224 de um <span class=\"greek\">λύχνος</span>. Pl.: Plut., Ant. 927 [26, 6], Pelop. 284 [12, 3] e outros lugares; Lucian, Philops. 31) Ac 16:29. Fogo, que fornece tanto luz quanto calor (X., Hell. 6, 2, 29; Cyr. 7, 5, 27; 1 Macc 12:29) Mk 14:54 (GBuchanan, ET 68, ’56, 27); Lk 22:56. Corpos celestes (Manetho, Apotel. 6, 146 sol e lua <span class=\"greek\">δύο</span> <span class=\"greek\">φῶτα</span>; igualmente Dio Chrys. 23 [40], 38; Ptolem., Apotel. 2, 13, 8; 3, 3, 3; 3, 5, 3 e outros lugares <span class=\"greek\">τὰ</span> <span class=\"greek\">φ</span>=constelações; Vett. Val. índice II p. 384; PGM 13, 400; Ps 135:7; Jer 4:23): Deus é <span class=\"greek\">πατὴρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">φώτων</span> Js 1:17 (TestAbr B 7 p. 111, 11 [Stone p. 70] <span class=\"greek\">φῶς</span> <span class=\"greek\">καλούμενον</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φωτός</span>; cf. ApcMos 36; 38); o sol como <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">τούτου</span> J 11:9 (Macrobius, Saturnal. 1, 23, 21 <span class=\"greek\">ἥλιε</span> <span class=\"greek\">παντοκράτορ</span>, … <span class=\"greek\">κόσμου</span> <span class=\"greek\">φῶς</span>; cf. Ps.-Demosth. 60, 24). Do olho como órgão de luz (Eur., Cycl. 633 <span class=\"greek\">φῶς</span> <span class=\"greek\">Κύκλωπος</span>; Ath. 32, 2) Mt 6:23; Lk 11:35.</p><p class=\"entry-text\">③ aquilo que é iluminado pela luz: <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φανερούμενον</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">ἐστιν</span> tudo o que se torna visível é (=está na) luz Eph 5:14.—CMugler, Dictionnaire historique de la terminologie optique des Grecs ’64.—B. 60. Cf. <span class=\"greek\">φέγγος</span>; v. Schmidt, Syn. I 563–98. DELG s.v. <span class=\"greek\">φάε</span>. Frisk s.v. <span class=\"greek\">φάος</span>. New Docs 1, 98f. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φωστήρ, ῆρος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φωστήρ</span>, <span class=\"greek\">ῆρος</span>, <span class=\"greek\">ὁ</span> (cf. <span class=\"greek\">φῶς</span>)</p><p class=\"entry-text\">① corpo que dá luz, especialmente dos corpos celestes, especificamente estrela (Heliod. 2, 24, 6; Vett. Val. 104, 30; 105, 7; Herm. Wr. 496, 2 Sc. [o sol]; Anth. Pal. 15, 17, 3 [cristão]; T. Kellis 22, 17 PGM 13, 298; IDefixWünsch 5, 23; Gen 1:14, 16; Wsd 13:2; Sir 43:7; En; PsSol 18:10;. SibOr 3, 88; TestLevi 14:3; TestJud 25:2; Ar.; Tat. 12, 4; Mel., P. 83, 618; 97, 740) Phil 2:15 (cf. Da 12:3; En 104:2 <span class=\"greek\">ὡσεὶ</span> <span class=\"greek\">φωστῆρες</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">ἀναλάμψετε</span>).—Em um texto fragmentário: [<span class=\"greek\">φ</span>]<span class=\"greek\">ωσ̣</span>[<span class=\"greek\">τὴ</span>]<span class=\"greek\">ρ</span> <span class=\"greek\">ἀπεδίκνυεν</span> (como faria) uma estrela, (o Senhor) mostrou (o caminho) (?) AcPl Ha 7. 35.</p><p class=\"entry-text\">② estado de brilho ou resplandecimento, esplendor, radiância (Anth. Pal. 11, 359, 7; 1 Esdr 8:76) Rv 21:11.—Cf. <span class=\"greek\">φέγγος</span>, v. Schmidt, Syn. I 563–98. DELG s.v. <span class=\"greek\">φάε</span> C. Frisk s.v. <span class=\"greek\">φάος</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φωσφόρος, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φωσφόρος</span>, <span class=\"greek\">ον</span> (cf. <span class=\"greek\">φῶς</span>, <span class=\"greek\">φέρω</span>; como adj. ‘que traz/dá luz’ Eur. e outros; pap, Philo) em nossa literatura somente uma vez e como subst. <span class=\"greek\">ὁ</span> <span class=\"greek\">φ</span>. provavelmente a estrela da manhã, o planeta Vênus (Eur., Ion 1157; Ps.-Pla., Tim. Locr. 96e; 97a; Plut., Mor. 430a; 601a; 889a e outros lugares; Cicero, Nat. Deor. 2, 20; Vett. Val. 236, 6; SibOr 5, 516; PRyl 524, 17; Neugebauer-Hoesen, glossário p. 200) fig. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:19</a> (v.l. <span class=\"greek\">ἑωσφόρος</span>). JBoehmer, ZNW 22, 1923, 228–33; FBoll, Sternglaube u. Sterndeutung 4 ’31, 47f.—FDölger, Ac V/1, ’35, 1ff interpreta o ‘portador de luz’ como significando o sol (este sentido de <span class=\"greek\">φ</span>. em Nicetas Eugen. 1, 87; 3, 21; 5, 258 Hercher); cf. HWindisch ad loc.—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φωταγωγός, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φωταγωγός</span>, <span class=\"greek\">ον</span> (cf. <span class=\"greek\">φῶς</span>, <span class=\"greek\">ἄγω</span>, e <span class=\"greek\">ἀγωγή</span> ‘condução para longe’; assim em Lucian e outros; PGM 5, 190; ApcSed 11:18 p. 135, 1 e 3 Ja.; <span class=\"greek\">φωταγωγία</span> em Vett. Val. 301, 22; ApcSed 16:7 p. 137, 14 Ja.; PGM 4, 955; <span class=\"greek\">φωταγωγέω</span> em Celsus 2, 71; TestAbr A 7 p. 84, 1f [Stone p. 16]; ParJer 5, 35; Mel., P. 72, 527 e outros lugares) que traz luz, que dá luz <span class=\"greek\">ἄγγελοι</span> <span class=\"greek\">φ</span>. anjos portadores de luz que estão postos sobre o caminho da luz B 18:1.—DELG s.v. <span class=\"greek\">φάε</span> D.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φωτεινός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φωτεινός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (cf. <span class=\"greek\">φῶς</span>; também -<span class=\"greek\">ινός</span> como En 22:2.—X. e outros; pseudepígr.; Just., A I, 32, 13; Tat. 13, 1; também comp. <span class=\"greek\">φωτεινότερος</span> Sir 17:31; 23:19; ApcSed 7:5; Just., D. 121, 2) brilhante, luminoso, radiante <span class=\"greek\">νεφέλη</span> <span class=\"greek\">φ</span>. uma nuvem luminosa que indica a presença de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:5</a>; GJs 19:2 (cf. X., Mem. 4, 3, 4 <span class=\"greek\">ἥλιος</span> <span class=\"greek\">φ</span>.). ApcPt 3:7 (cf. TestSol 12:3f C) das vestes radiantes dos anjos.—Oposto a <span class=\"greek\">σκοτεινός</span> (X., Mem. 3, 10, 1; En 22:2) iluminado, cheio de luz (Artem. 1, 64 <span class=\"greek\">βαλανεῖα</span> <span class=\"greek\">φωτεινά</span>; 2, 36) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:34,</a> 36ab.—DELG s.v. <span class=\"greek\">φάε</span> C. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φωτίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φωτίζω</span> fut. <span class=\"greek\">φωτίσω</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:5</a>; Rv 22:5) e <span class=\"greek\">φωτιῶ</span> (Rv 22:5 v.l.; TestLevi 4:3; v. Thackeray 228f); 1.º aor. <span class=\"greek\">ἐφώτισα</span>. Pass.: 1.º fut. 3.ª sg. pl. <span class=\"greek\">φωτισθήσεται</span>,-<span class=\"greek\">σονται</span>; 1.º aor. <span class=\"greek\">ἐφωτίσθην</span>; partic. perf. <span class=\"greek\">πεφωτισμένος</span> (cf. <span class=\"greek\">φῶς</span>; Aristot.+; ins, pap, LXX; En 5:8; Test12Patr; ParJer 9:3; Philo, Joseph., Just.; Mel., P. 35, 243 e outros lugares)</p><p class=\"entry-text\">① intr. (Aristot.; Theophr.; Plut., Num. 4, 9; 8, 2; Sir 42:16; Philo, Dec. 49) funcionar como fonte de luz, brilhar, de Deus (Ps 75:5) <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> sobre alguém Rv 22:5.</p><p class=\"entry-text\">② trans. fazer que seja iluminado, dar luz a, alumiar, iluminar (Aristarch. Sam. [III a.C.] p. 358, 20 e outros lugares; Diod S 3, 48, 4 do sol <span class=\"greek\">ἀκτῖσι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span>; Galen XIX p. 174 K.; PGM 3, 152; 4, 2345; IDefixWünsch 4, 14; 2 Esdr 19:12, 19 <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδόν</span>) <span class=\"greek\">τινά</span> alguém Lk 11:36; Rv 22:5 v.l.; <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span> Rv 21:23. Pass. (Anaximander, Vorsokr. 12 A 1 [em Diog. L. 2, 1] <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἡλίου</span>; Plut., Mor. 1120e; Diog. L. 7, 144 toda a terra <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">αὐτοῦ</span> [o sol] <span class=\"greek\">φωτίζεσθαι</span>) 18:1.</p><p class=\"entry-text\">③ trans. dar a conhecer com referência à vida interior ou a assuntos transcendentes e assim esclarecer, esclarecer, dar luz a, lançar luz sobre (<span class=\"greek\">φῶς</span> 2; 3) extensão fig. de 2</p><p class=\"entry-text\">ⓐ em linguagem figurada da luz celestial concedida ao ‘iluminado’ (cf. a oração PGM 4, 990, que invoca o <span class=\"greek\">μέγιστος</span> <span class=\"greek\">θεός</span> como <span class=\"greek\">τὸν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">φωτίζοντα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">διαυγάζοντα</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἰδίᾳ</span> <span class=\"greek\">δυνάμει</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σύμπαντα</span> <span class=\"greek\">κόσμον</span>; Herm. Wr. 1, 32 o inspirado ora a uma divindade por <span class=\"greek\">δύναμις</span> e <span class=\"greek\">χάρις</span>: <span class=\"greek\">ἵνα</span> <span class=\"greek\">φωτίσω</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγνοίᾳ</span>. V. também 13, 18; 19 <span class=\"greek\">τὸ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">σῷζε</span> <span class=\"greek\">ζωή</span>, <span class=\"greek\">φώτιζε</span> <span class=\"greek\">φῶς</span>, <span class=\"greek\">πνευμάτιζε</span> <span class=\"greek\">θεέ</span>; Philo, Fuga 139 e TestBenj 6:4 <span class=\"greek\">τ</span>. <span class=\"greek\">ψυχήν</span>; Sextus 97; ViHab 14 [p. 87, 6 Sch.].—GAnrich, Das antike Mysterienwesen 1894, 125f; GWobbermin, Religionsgesch. Studien 1896, 155ff; Rtzst., Mysterienrel. 3, 1927, 44; 264; 292); <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀληθινὸν</span> (isto é, Cristo, o Redentor celestial) <span class=\"greek\">φωτίζει</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἄνθρωπον</span> J 1:9 (v. Hdb. ad loc. e s.v. <span class=\"greek\">φῶς</span> 1b<span class=\"greek\">α</span>.—Para a combinação com <span class=\"greek\">φῶς</span>: ParJer 9:3; Cleom. [II d.C.] 2, 4 p. 188, 18 <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φωτίζον</span> <span class=\"greek\">αὐτόν</span>; Proclus sobre Pla., Cratyl. p. 103, 28 Pasqu.); <span class=\"greek\">φωτίσαι</span> <span class=\"greek\">πάντας</span> <span class=\"greek\">τίς</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκονομία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μυστηρίου</span> esclarecer a todos acerca do plano secreto/misterioso de Deus Eph 3:9 (talvez no sentido de ‘instruir’, cf. 4 Km 17:27f). Implora-se a Deus que conceda <span class=\"greek\">πεφωτισμένους</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὀφθαλμοὺς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> iluminados nos olhos de (vosso) coração = … vossa visão interior 1:18 (<span class=\"greek\">φωτίζειν</span> <span class=\"greek\">ὀφθαλμούς</span>: 2 Esdr 9:8; Ps 18:9; Bar 1:12). A comunidade cristã romana é <span class=\"greek\">πεφωτισμένη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">θελήματι</span> (isto é, de Deus) IRo ins (cf. Just., D. 122, 3 <span class=\"greek\">ἐθνῶν</span> <span class=\"greek\">πεφωτισμένων</span>). <span class=\"greek\">οἱ</span> <span class=\"greek\">ἅπαξ</span> <span class=\"greek\">φωτισθέντες</span> Hb 6:4; cf. 10:32.</p><p class=\"entry-text\">ⓑ trazer à luz, revelar <span class=\"greek\">τὶ</span> algo (Polyb. 22, 5, 10; Epict. 1, 4, 31 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀλήθειαν</span>; Plut., Mor. 902c; Jos., Ant. 8, 143 o sentido oculto de um enigma; pass., Lucian, Calum. 32; Mel., P. 41, 285 <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span>) <span class=\"greek\">τὰ</span> <span class=\"greek\">κρυπτὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκότους</span> aquilo que está oculto nas trevas 1 Cor 4:5. <span class=\"greek\">φ</span>. <span class=\"greek\">ζωὴν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀφθαρσίαν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">εὐαγγελίου</span> trazer à luz a vida e a imortalidade mediante o evangelho 2 Ti 1:10. Abs., seguido de pergunta indireta <span class=\"greek\">φωτίσαι</span> <span class=\"greek\">τίς</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκονομία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μυστηρίου</span> tornar claro qual é o plano misterioso (de Deus) Eph 3:9 v.l.—DELG s.v. <span class=\"greek\">φάε</span> C. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φωτισμός, οῦ, ὁ,</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φωτισμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span>, (<span class=\"greek\">φωτίζω</span>; iluminação no sentido físico: Strato de Lamps. [300 a.C.] Fgm. 76 Wehrli ’50; Petosiris, Fgm. 12 ln. 178 <span class=\"greek\">τῆς</span> <span class=\"greek\">σελήνης</span>; Sext. Emp., Math. 10, 224 <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἡλίου</span>; Plut., Mor. 929d; 931a; PMich 149, 3; 33 [II d.C.]; Ps 26:1; 43:4; 77:14; Job 3:9; Philo, Somn. 1, 53. Da luz do dia: <span class=\"greek\">ὁ</span> <span class=\"greek\">φ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἀέρος</span> Did., Gen. 23, 20) em nossa literatura somente em linguagem figurada (TestLevi 14:4 <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> … <span class=\"greek\">εἰς</span> <span class=\"greek\">φωτισμὸν</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">ἀνθρώπου</span>; Just., A I, 61, 12 <span class=\"greek\">καλεῖται</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">λουτρὸν</span> <span class=\"greek\">φωτισμός</span> [do batismo]) iluminação para a vida interior</p><p class=\"entry-text\">ⓐ esclarecimento, luz <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">αὐγάσαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">φωτισμὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">εὐαγγελίου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δόξης</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> para que não vejam a luz do evangelho da glória de Cristo 2 Cor 4:4 (v. <span class=\"greek\">αὐγάζω</span> 1).</p><p class=\"entry-text\">ⓑ ato de trazer à luz, revelação (<span class=\"greek\">φωτίζω</span> 3b) <span class=\"greek\">πρὸς</span> <span class=\"greek\">φωτισμὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γνώσεως</span> 2 Cor 4:6 (mas para outras interpretações v. os comentários. V. também Herm. Wr. 10, 21 <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γνώσεως</span> <span class=\"greek\">φῶς</span>; 7, 2a).—DELG s.v. <span class=\"greek\">φάε</span> C. M-M. TW. Sqicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0383-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><div class=\"section-title greek\" data-source-section=\"Χ\" data-source-line=\"76760\">Χ</div><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χαίρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χαίρω</span> variante média <span class=\"greek\">χαίρεται</span> TestAbr v. abaixo; imperf. <span class=\"greek\">ἔχαιρον</span>; fut. <span class=\"greek\">χαρήσομαι</span> (B-D-F §77; Mlt-H. 264); 2.º aor. pass. <span class=\"greek\">ἐχάρην</span> (Hom.+).</p><p class=\"entry-text\">① estar em estado de felicidade e bem-estar, alegrar-se, estar contente, oposto a <span class=\"greek\">κλαίειν</span> J 16:20; Ro 12:15ab (Damasc., Vi. Isid. 284 <span class=\"greek\">χαρίεις</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">χαρίεντας</span>); 1 Cor 7:30ab; Hv 3, 3, 2. Oposto a <span class=\"greek\">λύπην</span> <span class=\"greek\">ἔχειν</span> J 16:22. Com <span class=\"greek\">ἀγαλλιᾶσθαι</span> (Hab 3:18; TestJob 43:15; ParJer 6:20; cf. TestAbr A 11 p. 89, 17 [Stone p. 26]) Mt 5:12; 1 Pt 4:13b; cf. Rv 19:7; GJs 17:2. Com <span class=\"greek\">εὐφραίνεσθαι</span> (Jo 2:23 e outros lugares na LXX) Lk 15:32; Rv 11:10. Com <span class=\"greek\">σκιρτᾶν</span> Lk 6:23. Com acus. de obj. interno (B-D-F §153, 1; Rob. 477) <span class=\"greek\">χ</span>. <span class=\"greek\">χαρὰν</span> <span class=\"greek\">μεγάλην</span> alegrar-se muito (Jon 4:6; JosAs 3:4 e outros lugares) Mt 2:10. <span class=\"greek\">τῇ</span> <span class=\"greek\">χαρᾷ</span> <span class=\"greek\">ᾗ</span> (por atração em lugar de <span class=\"greek\">ἥν</span>) <span class=\"greek\">χαίρομεν</span> 1 Th 3:9. Também <span class=\"greek\">χαρᾷ</span> <span class=\"greek\">χ</span>., que provavelmente revela a influência do AT (Is 66:10), J 3:29 (B-D-F §198, 6; Rob. 531; 550). O partic. é usado com outros verbos com alegria, alegremente (Appian, Bell. Civ. 4, 40 §169 <span class=\"greek\">ἄπιθι</span> <span class=\"greek\">χαίρων</span>; 3 Km 8:66; Eutecnius 4 p. 43, 7 <span class=\"greek\">ἄπεισι</span> <span class=\"greek\">χαίρουσα</span>; Laud. Therap. 12 <span class=\"greek\">χαίρων</span> <span class=\"greek\">ἐστέλλετο</span>) <span class=\"greek\">ὑπεδέξατο</span> <span class=\"greek\">αὐτον</span> <span class=\"greek\">χαίρων</span> Lk 19:6; cf. v. 37; 15:5; Ac 5:41; 8:39.—O objeto ou motivo da alegria é indicado de vários modos: com simples dat. <span class=\"greek\">τοῖς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">λέγουσιν</span> os que são (meramente) loquazes Papias (2:3) (Aristonous 1, 45 [p. 164 Coll. Alex.]; Just., A I, 5, 3 e outros lugares; Orig., C. Cels. 8, 69, 20; v. também abaixo sobre Ro 12:12) ou prep. <span class=\"greek\">χαίρειν</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> alegrar-se por alguém ou algo (Soph. e outros; X., Cyr. 8, 4, 12, Mem. 2, 6, 35; Pla., Leg. 5, 729d; Diod S 1, 25, 2; Plut., Mor. 87e; 1088e; BGU 531 I, 4 [I d.C.]; POxy 41, 17; Tob 13:15ab; Pr 2:14; 24:19; Bar 4:33; JosAs 4:4; Jos., Ant. 1, 294; 3, 32; Ar. 15, 7; Just., D. 28, 4; Iren. 1, 16, 3 [Harv I 163, 9]) Mt 18:13; Lk 1:14; 13:17; Ac 15:31; Ro 16:19; 1 Cor 13:6; 16:17; 2 Cor 7:13; Rv 11:10; Hs 5, 2, 5 e 11; 8, 1, 16; 8, 5, 1 e 6; Dg 11:5. Também <span class=\"greek\">διά</span> com acus. (Appian, Bell. Civ. 4, 102 §428; EpArist 42) J 3:29; 11:15 a oração com <span class=\"greek\">ὅτι</span> dá o motivo, e <span class=\"greek\">δί</span> <span class=\"greek\">ὑμᾶς</span> significa por vossa causa = em vosso interesse; cf. 1 Th 3:9. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> (Soph., Trach. 1118; Pla., Rep. 10, 603c; En 104:13) Hs 1:11. <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> por isso Phil 1:18a (para outras funções de <span class=\"greek\">ἐν</span> v. abaixo). <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> em algo (Pla., Ep. 2, 310e.—<span class=\"greek\">περὶ</span> <span class=\"greek\">πλοῦτον</span> Did., Gen. 150, 8) 1 Cl 65:1. <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">λύπην</span> <span class=\"greek\">σχῶ</span> <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ὧν</span> <span class=\"greek\">ἔδει</span> <span class=\"greek\">με</span> <span class=\"greek\">χαίρειν</span> (seja <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ὧν</span>, seja <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">οἷς</span>) 2 Cor 2:3. O motivo ou objeto é dado por <span class=\"greek\">ὅτι</span> (Lucian, Charon 17; Ex 4:31; Just., A II, 2, 7) Lk 10:20b; J 11:15 (v. acima); 14:28; 2 Cor 7:9, 16; Phil 4:10; 2J 4. <span class=\"greek\">χ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">ὅτι</span> Lk 10:20a. <span class=\"greek\">χ</span>. <span class=\"greek\">ὅταν</span> 2 Cor 13:9. <span class=\"greek\">χ</span>. … <span class=\"greek\">γάρ</span> Phil 1:18b (19). O motivo ou obj. é expresso por um partic. (X., Cyr. 1, 5, 12; Pla., Rep. 5, 458a; Dio Chrys. 22 [39], 1 e outros lugares; PGM 4, 1212 <span class=\"greek\">χαίρεις</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">σοὺς</span> <span class=\"greek\">σῴζων</span>; 1611; Just., D. 114, 4): <span class=\"greek\">ἰδόντες</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀστέρα</span> <span class=\"greek\">ἐχάρησαν</span> Mt 2:10; cf. Lk 23:8; J 20:20; Ac 11:23; Phil 2:28; Hv 3, 12, 3. <span class=\"greek\">ἀκούσαντες</span> <span class=\"greek\">ἐχάρησαν</span> ficaram contentes com o que ouviram Mk 14:11; cf. Ac 13:48; Hv 3, 3, 2.—1 Cl 33:7; Dg 5:16. <span class=\"greek\">λαβόντες</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐδέμσματα</span> <span class=\"greek\">ἐχάρησαν</span> Hs 5, 2, 10. Com gen. e partic. (como Just., D. 85, 6) 9, 11, 7. Se <span class=\"greek\">χαίρειν</span> também está no partic., <span class=\"greek\">καί</span> vem entre os dois particípios: <span class=\"greek\">χαίρων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βλέπων</span> (e) é com alegria que vejo Col 2:5. <span class=\"greek\">ἐχάρην</span> <span class=\"greek\">ἐρχομένων</span> <span class=\"greek\">ἀδελφῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μαρτυρούντων</span> alegrei-me quando alguns irmãos cristãos vieram e testemunharam 3J 3.—<span class=\"greek\">τῇ</span> <span class=\"greek\">ἐλπίδι</span> <span class=\"greek\">χαίρ</span>. Ro 12:12 não é ‘alegrar-se por causa da esperança’ (o dat. ocorre neste sentido X., Mem. 1, 5, 4; Theopompus [IV a.C.]: 115 Fgm. 114 Jac.; Epict., App. D, 3 [p. 479 Sch.] <span class=\"greek\">ἀρετῇ</span> <span class=\"greek\">χ</span>.; Iambl., Vi. Pyth. 28, 137 <span class=\"greek\">οἷς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">χ</span>.; Pr 17:19), mas antes alegrar-se na esperança ou cheio de esperança (B-D-F §196). <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">χαίρω</span> no que vos diz respeito, alegro-me Ro 16:19 v.l. Na maioria dos casos em nossa literatura <span class=\"greek\">ἐν</span> não introduz a causa da alegria (v. acima): <span class=\"greek\">χαίρω</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">παθήμασιν</span> alegro-me em meio a (embora por causa de também seja possível) (os) sofrimento(s) Col 1:24 (o inglês ‘in’ transmite ambas as ideias). <span class=\"greek\">χαίρ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span> Phil 3:1; 4:4a, 10 (os imperativos em 3:1; 4:4ab são traduzidos como adeus [assim Hom. e outros] por Goodsp., v. Probs. 174f; isto os classificaria sob 2a abaixo). Abs. Lk 22:5; J 4:36; 8:56 (EbNestle, Abraham Rejoiced: ET 20, 1909, 477; JMoulton, ‘Abraham Rejoiced’: ibid. 523–28); 2 Cor 6:10; 7:7; 13:11; Phil 2:17f; 4:4b (v. Goodsp. acima); 1 Th 5:16; 1 Pt 4:13a; cf. 13b; GPt 6:23; Hv 3, 3, 3f; Hs 1:11; 5, 3, 3; GJs 16:3.—Sobre a rara média <span class=\"greek\">χαιρόμενος</span> (TestAbr A 11 p. 89, 21 [Stone p. 26] <span class=\"greek\">χαίρεται</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀγάλλεται</span>) Ac 3:8 D, v. Mlt. 161 com nota 1; B-D-F §307.</p><p class=\"entry-text\">② no imperativo, saudação convencional que deseja o bem a alguém; também no indicativo, empregar tal saudação (com efeito, expressar que se está em boas relações com o outro, cf. Soph., Oed. R. 596 <span class=\"greek\">νῦν</span> <span class=\"greek\">πᾶσι</span> <span class=\"greek\">χαίρω</span>=agora desejo bom dia a todos)</p><p class=\"entry-text\">ⓐ no tratamento oral, frequentemente ao encontrar pessoas (Hom. e outros; também <span class=\"greek\">χαίροις</span> TestAbr A 16 p. 97, 21 [Stone p. 42]; B 13 p. 117, 18 [82]; JosAs 8:2; GrBar 11:6f; empréstimo na literatura rabínica) <span class=\"greek\">χαῖρε</span>, <span class=\"greek\">χαίρετε</span> bem-vindo(s), bom dia, salve(-vos), alegro-me em ver-vos, às vezes (p. ex. Hermas)=como vai(s)? ou simplesmente olá Mt 26:49; 27:29; 28:9 (aqui talvez especificamente bom dia [Lucian, Laps. inter Salutandum 1 <span class=\"greek\">τὸ</span> <span class=\"greek\">ἑωθινὸν</span> … <span class=\"greek\">χαίρειν</span>; também escólios p. 234, 13 Rabe; Cass. Dio 69, 18; Nicetas Eugen. 2, 31 H.; assim Goodsp., Probs. 45f; traduz Lk 1:28 e as passagens de 2J e H do mesmo modo]); Mk 15:18; Lk 1:28; GJs 11:1 (Ps.-Callisth. 1, 4, 2 Nectanebo diz a Olímpia ao entrar em seu aposento: <span class=\"greek\">χαίροις</span> <span class=\"greek\">Μακεδόνων</span> <span class=\"greek\">βασίλεια</span>); J 19:3 (sobre a saudação sarcástica como rei cf. Diod S 34 + 35, Fgm. 2, 8f [Eunus]); Hv 1, 1, 4; 1, 2, 2ab; 4, 2, 2ab. <span class=\"greek\">χαίρειν</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">λέγειν</span> saudar alguém, desejar bom dia a alguém (Epict. 3, 22, 64; pass.: <span class=\"greek\">χαίρειν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὑφ</span>’ <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">λέγεσθαι</span> Iren. 1, 16, 3 [Harv. I 162, 11]) 2J 10f.—Sobre o possível sentido de despedida, adeus para Phil 3:1; 4:4 v. 1 acima, final.</p><p class=\"entry-text\">ⓑ elipticamente no início de uma carta, saudações (X., Cyr. 4, 5, 27; Theocr. 14, 1; Plut., Ages. 607 [21, 10]=Mor. 213a; Aelian, VH 1, 25; Jos., Vi. 217; 365; Mel., HE 4, 26, 13; pap [Mitt-Wilck. I/2, 477–82; HLietzmann, Griech. Pap.: Kl. T. 142, 1910; Witkowski, Epistulae; GMilligan, Selections fr. the Gk. Pap.2 1911]; LXX.—B-D-F §389; 480, 5; Rob. 944; 1093. GGerhard, Untersuchungen zur Gesch. des griech. Briefes, diss. Heidelb. 1903, Philol 64, 1905, 27–65; FZiemann, De Epistularum Graecarum Formulis Sollemnibus: Dissertationes Philologicae Halenses XVIII/4, 1911; PWendland, Die urchristl. Literaturformen2, 3 1912, 411–17 [Suppl. 15: Formalien des Briefes]; WSchubart, Einführung in die Papyruskunde 1918; Dssm., LO 116ff=LAE 146ff [literatura]; FExler, The Form of the Ancient Gk. Letter 1923; ORoller, D. Formular d. paul. Briefe ’33; RArcher, The Ep. Form in the NT: ET 63, ’51f, 296–98; Pauly-W. III 836ff; VII 1192ff; Kl. Pauly II 324–27; BHHW I 272f) <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀδελφοῖς</span> … <span class=\"greek\">χαίρειν</span> saudações aos irmãos Ac 15:23; cf. 23:26; Js 1:1; AcPlCor 1:1; 2:1. Ign. usa a fórmula comum <span class=\"greek\">πλεῖστα</span> <span class=\"greek\">χαίρειν</span> (<span class=\"greek\">πολύς</span> 3b<span class=\"greek\">α</span>) IEph ins; IMg ins; ITr ins; IRo ins; ISm ins; IPol ins.—A introdução de B é singular: <span class=\"greek\">χαίρετε</span>, <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θυγατέρες</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">κυρίου</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">εἰρήνῃ</span> 1:1.—JLieu, ‘Grace to you and Peace’, The Apostolic Greeting: BJRL 68, ’85, 161–78.—Schmidt, Syn. II 550–73. DELG. M-M. EDNT. TW.</p></section></article>"};
